import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Restaurant, MenuItem, Ad, OrderCategory, District } from '../types';
import { OrderStatus, UserStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Constants
import { DEFAULT_PRICING, MENOFIA_DATA } from '../config/constants';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, doc, onSnapshot, orderBy, 
  setDoc, addDoc, deleteDoc, updateDoc, limit, getDoc, where, increment
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  User as UserIcon, DollarSign, Bike, Search, Car, 
  ShieldCheck, Megaphone, Trash2, Save, Loader2, MessageCircle, 
  Calculator, TrendingUp, ChevronRight, MapPin, 
  LayoutDashboard, Send, Users2, Plus, X, Building2, UtensilsCrossed,
  Image as ImageIcon, PlusCircle, Camera, FileText, Edit3, Wallet,
  ShieldAlert, ChevronLeft, Eye, MousePointer2, Settings2, Flame,
  Store, CheckCircle2, Circle, Key, Hash, Mail, Fingerprint,
  Zap, Building, Map as MapIcon, ChevronDown, Globe
} from 'lucide-react';

// --- مكون إدارة المراكز والقرى (Village & District Manager) ---
const VillageDistrictManager: React.FC = () => {
  const [districts, setDistricts] = useState<District[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAddingDistrict, setIsAddingDistrict] = useState(false);
  const [newDistrictName, setNewDistrictName] = useState('');
  const [expandedDistrict, setExpandedDistrict] = useState<string | null>(null);
  const [newVillageData, setNewVillageData] = useState({ name: '', lat: 30.5, lng: 31.0 });

  useEffect(() => {
    // جلب البيانات من Firestore لضمان التزامن
    const q = query(collection(db, "districts"), orderBy("name", "asc"));
    return onSnapshot(q, (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[];
      setDistricts(data);
      setLoading(false);
    });
  }, []);

  const addDistrict = async () => {
    if (!newDistrictName.trim()) return;
    try {
      const id = `dist_${Date.now()}`;
      await setDoc(doc(db, "districts", id), {
        id,
        name: newDistrictName.trim(),
        villages: []
      });
      setNewDistrictName('');
      setIsAddingDistrict(false);
    } catch (e) { alert('خطأ في إضافة المركز'); }
  };

  const deleteDistrict = async (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المركز وكافة القرى التابعة له؟')) {
      await deleteDoc(doc(db, "districts", id));
    }
  };

  const addVillage = async (districtId: string) => {
    if (!newVillageData.name.trim()) return;
    const district = districts.find(d => d.id === districtId);
    if (!district) return;

    try {
      const newVillage: Village = {
        id: `vill_${Date.now()}`,
        name: newVillageData.name.trim(),
        center: { lat: Number(newVillageData.lat), lng: Number(newVillageData.lng) }
      };

      const updatedVillages = [...(district.villages || []), newVillage];
      await updateDoc(doc(db, "districts", districtId), {
        villages: updatedVillages
      });
      setNewVillageData({ name: '', lat: 30.5, lng: 31.0 });
    } catch (e) { alert('خطأ في إضافة القرية'); }
  };

  const removeVillage = async (districtId: string, villageId: string) => {
    const district = districts.find(d => d.id === districtId);
    if (!district) return;

    try {
      const updatedVillages = district.villages.filter(v => v.id !== villageId);
      await updateDoc(doc(db, "districts", districtId), {
        villages: updatedVillages
      });
    } catch (e) { alert('خطأ في حذف القرية'); }
  };

  return (
    <div className="space-y-6 animate-reveal">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 flex justify-between items-center flex-row-reverse">
         <div className="text-right">
            <h3 className="text-xl font-black text-slate-900">إدارة جغرافيا المنوفية</h3>
            <p className="text-[9px] font-bold text-slate-400 uppercase">المراكز، القرى، والإحداثيات</p>
         </div>
         <button onClick={() => setIsAddingDistrict(!isAddingDistrict)} className="p-4 bg-[#2D9469] text-white rounded-2xl shadow-lg active:scale-90 transition-all flex items-center gap-2">
            {isAddingDistrict ? <X className="h-5 w-5" /> : <><Plus className="h-5 w-5" /> إضافة مركز</>}
         </button>
      </div>

      {isAddingDistrict && (
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-50 space-y-6 animate-in zoom-in duration-300">
           <div className="flex items-center gap-4 flex-row-reverse">
              <div className="bg-emerald-50 p-4 rounded-2xl text-[#2D9469]"><Building className="h-6 w-6" /></div>
              <div className="flex-1">
                 <label className="text-[10px] font-black text-slate-400 block mb-1 text-right">اسم المركز الجديد (مثل: أشمون)</label>
                 <input 
                   autoFocus
                   value={newDistrictName} 
                   onChange={e => setNewDistrictName(e.target.value)} 
                   placeholder="اكتب اسم المركز..." 
                   className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right border-2 border-transparent focus:border-emerald-500 transition-all" 
                 />
              </div>
           </div>
           <button onClick={addDistrict} className="w-full bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg shadow-2xl active:scale-95 transition-all">
              تأكيد إضافة المركز
           </button>
        </div>
      )}

      <div className="space-y-4">
         {loading ? (
           <div className="py-20 flex justify-center"><Loader2 className="animate-spin h-10 w-10 text-emerald-500" /></div>
         ) : districts.length === 0 ? (
           <div className="py-24 text-center text-slate-300 font-bold border-4 border-dashed border-slate-50 rounded-[4rem]">لا توجد مراكز مضافة بعد</div>
         ) : districts.map(dist => (
           <div key={dist.id} className="bg-white rounded-[3rem] border border-slate-100 shadow-sm overflow-hidden transition-all">
              <div 
                onClick={() => setExpandedDistrict(expandedDistrict === dist.id ? null : dist.id)}
                className={`p-6 flex justify-between items-center cursor-pointer transition-colors ${expandedDistrict === dist.id ? 'bg-slate-50' : 'hover:bg-slate-50/50'}`}
              >
                 <div className="flex gap-2">
                    <button onClick={(e) => { e.stopPropagation(); deleteDistrict(dist.id); }} className="p-3 text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"><Trash2 className="h-4 w-4" /></button>
                    <ChevronDown className={`h-5 w-5 text-slate-300 transition-transform duration-500 ${expandedDistrict === dist.id ? 'rotate-180' : ''}`} />
                 </div>
                 <div className="flex items-center gap-4 flex-row-reverse text-right">
                    <div className="bg-slate-100 p-3 rounded-2xl text-slate-400"><MapIcon className="h-5 w-5" /></div>
                    <div>
                       <h4 className="font-black text-slate-900">مركز {dist.name}</h4>
                       <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{dist.villages?.length || 0} قرية مسجلة</p>
                    </div>
                 </div>
              </div>

              {expandedDistrict === dist.id && (
                <div className="p-6 border-t border-slate-100 space-y-6 animate-in slide-in-from-top duration-300">
                   {/* قائمة القرى */}
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {dist.villages?.map(v => (
                        <div key={v.id} className="bg-slate-50 p-4 rounded-2xl flex justify-between items-center flex-row-reverse group">
                           <div className="text-right">
                              <p className="font-black text-slate-800 text-xs">{v.name}</p>
                              <p className="text-[8px] font-bold text-slate-400" dir="ltr">{v.center.lat.toFixed(3)}, {v.center.lng.toFixed(3)}</p>
                           </div>
                           <button onClick={() => removeVillage(dist.id, v.id)} className="p-2 text-rose-200 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100"><X className="h-4 w-4" /></button>
                        </div>
                      ))}
                      {(!dist.villages || dist.villages.length === 0) && (
                        <p className="col-span-full text-center text-slate-300 text-[10px] py-4 font-bold">لا توجد قرى في هذا المركز</p>
                      )}
                   </div>

                   {/* إضافة قرية جديدة */}
                   <div className="bg-emerald-50/30 p-6 rounded-[2.5rem] border-2 border-emerald-50 space-y-4">
                      <div className="text-right mb-2"><h5 className="text-[10px] font-black text-[#2D9469] uppercase tracking-widest">إضافة قرية / منطقة جديدة</h5></div>
                      <div className="grid grid-cols-1 gap-3">
                         <input 
                           value={newVillageData.name} 
                           onChange={e => setNewVillageData({...newVillageData, name: e.target.value})} 
                           placeholder="اسم القرية" 
                           className="w-full bg-white p-4 rounded-xl text-xs font-black outline-none text-right shadow-sm" 
                         />
                         <div className="grid grid-cols-2 gap-2">
                            <input 
                              type="number" 
                              value={newVillageData.lat} 
                              onChange={e => setNewVillageData({...newVillageData, lat: Number(e.target.value)})} 
                              placeholder="خط العرض" 
                              className="w-full bg-white p-4 rounded-xl text-[10px] font-bold outline-none text-center shadow-sm" 
                            />
                            <input 
                              type="number" 
                              value={newVillageData.lng} 
                              onChange={e => setNewVillageData({...newVillageData, lng: Number(e.target.value)})} 
                              placeholder="خط الطول" 
                              className="w-full bg-white p-4 rounded-xl text-[10px] font-bold outline-none text-center shadow-sm" 
                            />
                         </div>
                      </div>
                      <button onClick={() => addVillage(dist.id)} className="w-full bg-[#2D9469] text-white py-4 rounded-2xl font-black text-xs shadow-lg active:scale-95 transition-all">إضافة القرية للقاعدة</button>
                   </div>
                </div>
              )}
           </div>
         ))}
      </div>
    </div>
  );
};

// --- نافذة تعديل المستخدم الشاملة (Portrait Optimized) ---
const UserEditModal: React.FC<{ user: User, onClose: () => void }> = ({ user, onClose }) => {
  const [formData, setFormData] = useState({
    name: user.name || '',
    phone: user.phone || '',
    email: user.email || '',
    password: user.password || '',
    role: user.role || 'CUSTOMER',
    status: user.status || 'APPROVED',
    balance: user.wallet?.balance || 0,
    vehicleType: user.vehicleType || 'TOKTOK',
    plateNumber: user.plateNumber || ''
  });
  const [loading, setLoading] = useState(false);

  const handleSave = async () => {
    setLoading(true);
    try {
      await updateDoc(doc(db, "users", user.id), {
        name: formData.name,
        phone: formData.phone,
        email: formData.email,
        password: formData.password,
        role: formData.role,
        status: formData.status,
        vehicleType: formData.role === 'DRIVER' ? formData.vehicleType : null,
        plateNumber: formData.role === 'DRIVER' ? formData.plateNumber : null,
        "wallet.balance": Number(formData.balance)
      });
      onClose();
    } catch (e) {
      alert('حدث خطأ أثناء تحديث البيانات');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-white sm:bg-slate-950/80 sm:backdrop-blur-md flex items-end sm:items-center justify-center animate-in fade-in duration-300">
       <div className="bg-white w-full h-full sm:h-auto sm:max-w-2xl sm:rounded-[3rem] shadow-2xl flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden">
          {/* Header */}
          <div className="p-6 border-b border-slate-50 flex justify-between items-center sticky top-0 bg-white z-10 shadow-sm">
             <button onClick={onClose} className="p-3 bg-slate-50 text-slate-400 rounded-2xl active:scale-90 transition-all">
                <ChevronLeft className="h-6 w-6" />
             </button>
             <div className="text-right">
                <h3 className="text-xl font-black text-slate-900 tracking-tight">إدارة العضوية</h3>
                <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">تعديل كامل البيانات</p>
             </div>
          </div>

          {/* Scrollable Form Body */}
          <div className="flex-1 overflow-y-auto p-6 space-y-10 no-scrollbar pb-32">
             {/* القسم الأساسي */}
             <div className="space-y-4">
                <div className="flex items-center gap-2 justify-end text-slate-400 mb-2">
                   <span className="text-[10px] font-black uppercase tracking-widest">المعلومات الشخصية</span>
                   <UserIcon className="h-4 w-4" />
                </div>
                <div className="grid grid-cols-1 gap-4">
                   <div className="bg-slate-50 p-4 rounded-2xl border-2 border-transparent focus-within:border-emerald-500 transition-all shadow-inner">
                      <label className="text-[8px] font-black text-slate-400 mr-2 mb-1 block">الاسم بالكامل</label>
                      <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-transparent font-black text-sm outline-none text-right" />
                   </div>
                   <div className="grid grid-cols-2 gap-3">
                      <div className="bg-slate-50 p-4 rounded-2xl border-2 border-transparent focus-within:border-emerald-500 transition-all shadow-inner">
                         <label className="text-[8px] font-black text-slate-400 mr-2 mb-1 block">رقم الموبايل</label>
                         <input value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-transparent font-black text-sm outline-none text-left" dir="ltr" />
                      </div>
                      <div className="bg-slate-50 p-4 rounded-2xl border-2 border-transparent focus-within:border-emerald-500 transition-all shadow-inner">
                         <label className="text-[8px] font-black text-slate-400 mr-2 mb-1 block">البريد الإلكتروني</label>
                         <input value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full bg-transparent font-black text-[10px] outline-none text-left" dir="ltr" />
                      </div>
                   </div>
                </div>
             </div>

             {/* قسم الأمان والحالة */}
             <div className="space-y-4">
                <div className="flex items-center gap-2 justify-end text-rose-500 mb-2">
                   <span className="text-[10px] font-black uppercase tracking-widest">إدارة الحساب</span>
                   <ShieldAlert className="h-4 w-4" />
