                   <div className="bg-rose-50/30 p-4 rounded-2xl border-2 border-transparent focus-within:border-rose-500 transition-all shadow-inner">
                      <label className="text-[8px] font-black text-rose-400 mr-2 mb-1 block">كلمة المرور</label>
                      <div className="flex items-center gap-2">
                         <Key className="h-4 w-4 text-rose-200 shrink-0" />
                         <input value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="w-full bg-transparent font-black text-sm outline-none text-left" dir="ltr" />
                      </div>
                   </div>
                   <div className="grid grid-cols-2 gap-3">
                      <div className="bg-slate-50 p-4 rounded-2xl shadow-inner">
                         <label className="text-[8px] font-black text-slate-400 mr-2 mb-1 block">صلاحية الحساب</label>
                         <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as any})} className="w-full bg-transparent font-black text-[11px] outline-none text-right">
