                      </div>
                   </div>
                </div>
             </div>

             {/* الرصيد والمحفظة */}
             <div className="space-y-4">
                <div className="flex items-center gap-2 justify-end text-emerald-600 mb-2">
                   <span className="text-[10px] font-black uppercase tracking-widest">إدارة المحفظة</span>
                   <Wallet className="h-4 w-4" />
                </div>
                <div className="bg-emerald-600 p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden">
                   <div className="absolute top-0 left-0 w-32 h-full bg-white/10 blur-3xl"></div>
                   <div className="relative z-10 text-center space-y-4">
                      <p className="text-[10px] font-black opacity-60 uppercase tracking-widest">الرصيد المتاح</p>
                      <input type="number" value={formData.balance} onChange={e => setFormData({...formData, balance: Number(e.target.value)})} className="w-full bg-white/20 border-2 border-white/20 rounded-2xl p-4 text-4xl font-black text-center outline-none focus:bg-white focus:text-emerald-700 transition-all" />
                      <p className="text-[9px] font-bold opacity-60">* التغيير يظهر للمستخدم فوراً</p>
                   </div>
                </div>
             </div>

             {/* بيانات المركبة للكباتن */}
             {formData.role === 'DRIVER' && (
                <div className="space-y-4 animate-in slide-in-from-top">
                   <div className="flex items-center gap-2 justify-end text-blue-500 mb-2">
                      <span className="text-[10px] font-black uppercase tracking-widest">بيانات الكابتن</span>
                      <Car className="h-4 w-4" />
                   </div>
                   <div className="grid grid-cols-2 gap-3">
                      <div className="bg-blue-50/50 p-4 rounded-2xl shadow-inner border border-blue-100">
                         <label className="text-[8px] font-black text-blue-400 mr-2 mb-1 block">نوع المركبة</label>
                         <select value={formData.vehicleType} onChange={e => setFormData({...formData, vehicleType: e.target.value as any})} className="w-full bg-transparent font-black text-xs outline-none text-right">
                            <option value="TOKTOK">توكتوك</option>
                            <option value="MOTORCYCLE">موتوسيكل</option>
                            <option value="CAR">سيارة</option>
                         </select>
                      </div>
                      <div className="bg-blue-50/50 p-4 rounded-2xl shadow-inner border border-blue-100">
                         <label className="text-[8px] font-black text-blue-400 mr-2 mb-1 block">رقم اللوحة</label>
                         <div className="flex items-center gap-2">
                            <Hash className="h-4 w-4 text-blue-200" />
                            <input value={formData.plateNumber} onChange={e => setFormData({...formData, plateNumber: e.target.value})} className="w-full bg-transparent font-black text-sm outline-none text-center" placeholder="أ ب ج 1" />
