             <button onClick={onClose} className="flex-1 py-5 rounded-[1.8rem] font-black text-slate-400 active:scale-95 transition-all">إلغاء</button>
             <button onClick={handleSave} disabled={loading} className="flex-[2] bg-slate-950 text-white py-5 rounded-[1.8rem] font-black text-lg shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                {loading ? <Loader2 className="animate-spin h-5 w-5" /> : 'حفظ التعديلات'}
             </button>
          </div>
       </div>
    </div>
  );
};

// --- مكون إدارة الإعلانات (Ad Manager) ---
const AdManager: React.FC = () => {
  const [ads, setAds] = useState<Ad[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [adData, setAdData] = useState<Partial<Ad>>({
    title: '', description: '', type: 'general', isActive: true, displayOrder: 0
  });
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const q = query(collection(db, "ads"), orderBy("displayOrder", "asc"));
    return onSnapshot(q, (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[];
      setAds(data.sort((a, b) => (a.displayOrder || 0) - (b.displayOrder || 0)));
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setAdData(prev => ({ ...prev, imageUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const saveAd = async () => {
    if (!adData.title || !adData.imageUrl) return alert('يرجى إكمال بيانات الإعلان');
    setLoading(true);
    try {
      const id = adData.id || `ad_${Date.now()}`;
      await setDoc(doc(db, "ads", id), {
        ...adData,
        id,
        views: adData.views || 0,
        clicks: adData.clicks || 0,
        createdAt: adData.createdAt || Date.now()
      });
      setIsAdding(false);
      setAdData({ title: '', description: '', type: 'general', isActive: true, displayOrder: 0 });
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  return (
    <div className="space-y-6 animate-reveal">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 flex justify-between items-center flex-row-reverse">
         <div className="text-right">
            <h3 className="text-xl font-black text-slate-900">إدارة الإعلانات</h3>
            <p className="text-[9px] font-bold text-slate-400 uppercase">الترويج والعروض الحصرية</p>
         </div>
         <button onClick={() => setIsAdding(!isAdding)} className="p-4 bg-emerald-600 text-white rounded-2xl shadow-lg active:scale-90 transition-all">
            {isAdding ? <X className="h-5 w-5" /> : <Plus className="h-5 w-5" />}
         </button>
      </div>

      {isAdding && (
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-50 space-y-6 animate-in zoom-in duration-300">
           <div 
             onClick={() => fileRef.current?.click()}
             className="w-full h-48 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-emerald-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden group transition-all"
           >
              {adData.imageUrl ? (
                <img src={adData.imageUrl} className="w-full h-full object-cover" />
              ) : (
                <>
                  <ImageIcon className="h-10 w-10 text-emerald-200 mb-2" />
                  <p className="text-[10px] font-black text-emerald-300 uppercase">ارفع صورة الإعلان</p>
                </>
              )}
           </div>
           <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

