                 <div className="flex-1 text-right">
                    <h4 className="font-black text-slate-900 text-sm">{ad.title}</h4>
                    <p className="text-[10px] font-bold text-slate-400 line-clamp-2 mt-1">{ad.description}</p>
                    <div className="flex items-center gap-3 justify-end mt-2">
                       <span className="text-[8px] font-black bg-slate-100 text-slate-400 px-2 py-0.5 rounded-full">{ad.type}</span>
                       <div className={`w-1.5 h-1.5 rounded-full ${ad.isActive ? 'bg-emerald-500' : 'bg-slate-300'}`}></div>
                    </div>
                 </div>
              </div>

              <div className="flex justify-between items-center pt-3 border-t border-slate-50">
                 <div className="flex gap-4">
                    <div className="flex items-center gap-1.5">
                       <Eye className="h-3 w-3 text-slate-300" />
                       <span className="text-[10px] font-black text-slate-400">{ad.views}</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                       <MousePointer2 className="h-3 w-3 text-emerald-400" />
                       <span className="text-[10px] font-black text-emerald-600">{ad.clicks}</span>
                    </div>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => { setAdData(ad); setIsAdding(true); }} className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:text-emerald-600 transition-all"><Edit3 className="h-4 w-4" /></button>
                    <button onClick={async () => { if(confirm('حذف الإعلان؟')) await deleteDoc(doc(db, "ads", ad.id)); }} className="p-3 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 className="h-4 w-4" /></button>
                 </div>
