// --- مكون إدارة المراكز والقرى (Village & District Manager) ---
const VillageDistrictManager: React.FC = () => {
  const [districts, setDistricts] = useState<District[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAddingDistrict, setIsAddingDistrict] = useState(false);
  const [newDistrictName, setNewDistrictName] = useState('');
  const [expandedDistrict, setExpandedDistrict] = useState<string | null>(null);
  const [newVillageData, setNewVillageData] = useState({ name: '', lat: 30.5, lng: 31.0 });

  // حالات التعديل الجديدة
  const [editingDistrictId, setEditingDistrictId] = useState<string | null>(null);
  const [tempDistrictName, setTempDistrictName] = useState('');
  const [editingVillageId, setEditingVillageId] = useState<string | null>(null);
  const [tempVillageData, setTempVillageData] = useState<Village | null>(null);

  useEffect(() => {
    const q = query(collection(db, "districts"), orderBy("name", "asc"));
    return onSnapshot(q, (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[];
      setDistricts(data);
      setLoading(false);
    });
  }, []);

  const addDistrict = async () => {
    if (!newDistrictName.trim()) return;
    try {
      const id = `dist_${Date.now()}`;
      await setDoc(doc(db, "districts", id), {
        id,
        name: newDistrictName.trim(),
        villages: []
      });
      setNewDistrictName('');
      setIsAddingDistrict(false);
    } catch (e) { alert('خطأ في إضافة المركز'); }
  };

  const deleteDistrict = async (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المركز وكافة القرى التابعة له؟')) {
      await deleteDoc(doc(db, "districts", id));
    }
  };

  const startEditDistrict = (dist: District) => {
    setEditingDistrictId(dist.id);
    setTempDistrictName(dist.name);
  };

  const saveDistrictName = async (id: string) => {
    if (!tempDistrictName.trim()) return;
    try {
      await updateDoc(doc(db, "districts", id), { name: tempDistrictName.trim() });
      setEditingDistrictId(null);
    } catch (e) { alert('خطأ في التحديث'); }
  };

  const addVillage = async (districtId: string) => {
    if (!newVillageData.name.trim()) return;
    const district = districts.find(d => d.id === districtId);
    if (!district) return;

    try {
      const newVillage: Village = {
        id: `vill_${Date.now()}`,
        name: newVillageData.name.trim(),
        center: { lat: Number(newVillageData.lat), lng: Number(newVillageData.lng) }
      };

      const updatedVillages = [...(district.villages || []), newVillage];
      await updateDoc(doc(db, "districts", districtId), {
        villages: updatedVillages
      });
      setNewVillageData({ name: '', lat: 30.5, lng: 31.0 });
    } catch (e) { alert('خطأ في إضافة القرية'); }
  };

  const removeVillage = async (districtId: string, villageId: string) => {
    const district = districts.find(d => d.id === districtId);
    if (!district) return;
    if (!confirm('حذف هذه القرية؟')) return;

    try {
      const updatedVillages = district.villages.filter(v => v.id !== villageId);
      await updateDoc(doc(db, "districts", districtId), {
        villages: updatedVillages
      });
    } catch (e) { alert('خطأ في حذف القرية'); }
  };

  const startEditVillage = (vill: Village) => {
    setEditingVillageId(vill.id);
    setTempVillageData({ ...vill });
  };

  const saveVillageChanges = async (districtId: string) => {
    if (!tempVillageData || !tempVillageData.name.trim()) return;
    const district = districts.find(d => d.id === districtId);
    if (!district) return;

    try {
      const updatedVillages = district.villages.map(v => 
        v.id === tempVillageData.id ? tempVillageData : v
      );
      await updateDoc(doc(db, "districts", districtId), { villages: updatedVillages });
      setEditingVillageId(null);
      setTempVillageData(null);
    } catch (e) { alert('خطأ في حفظ بيانات القرية'); }
  };

  return (
    <div className="space-y-6 animate-reveal">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 flex justify-between items-center flex-row-reverse">
         <div className="text-right">
            <h3 className="text-xl font-black text-slate-900">إدارة جغرافيا المنوفية</h3>
            <p className="text-[9px] font-bold text-slate-400 uppercase">تعديل المراكز والقرى والإحداثيات</p>
         </div>
         <button onClick={() => setIsAddingDistrict(!isAddingDistrict)} className="p-4 bg-[#2D9469] text-white rounded-2xl shadow-lg active:scale-90 transition-all flex items-center gap-2">
            {isAddingDistrict ? <X className="h-5 w-5" /> : <><Plus className="h-5 w-5" /> إضافة مركز</>}
         </button>
      </div>

      {isAddingDistrict && (
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-50 space-y-6 animate-in zoom-in duration-300">
           <div className="flex items-center gap-4 flex-row-reverse">
              <div className="bg-emerald-50 p-4 rounded-2xl text-[#2D9469]"><Building className="h-6 w-6" /></div>
              <div className="flex-1">
                 <label className="text-[10px] font-black text-slate-400 block mb-1 text-right">اسم المركز الجديد</label>
                 <input 
                   autoFocus
                   value={newDistrictName} 
                   onChange={e => setNewDistrictName(e.target.value)} 
                   placeholder="اكتب اسم المركز..." 
                   className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right border-2 border-transparent focus:border-emerald-500 transition-all" 
                 />
              </div>
           </div>
           <button onClick={addDistrict} className="w-full bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg shadow-2xl active:scale-95 transition-all">
              تأكيد إضافة المركز
           </button>
        </div>
      )}

      <div className="space-y-4">
         {loading ? (
           <div className="py-20 flex justify-center"><Loader2 className="animate-spin h-10 w-10 text-emerald-500" /></div>
         ) : districts.length === 0 ? (
           <div className="py-24 text-center text-slate-300 font-bold border-4 border-dashed border-slate-50 rounded-[4rem]">لا توجد مراكز مضافة بعد</div>
         ) : districts.map(dist => (
           <div key={dist.id} className="bg-white rounded-[3rem] border border-slate-100 shadow-sm overflow-hidden transition-all">
              <div 
                className={`p-6 flex justify-between items-center transition-colors ${expandedDistrict === dist.id ? 'bg-slate-50' : 'hover:bg-slate-50/50'}`}
              >
                 <div className="flex gap-2 items-center">
                    <button onClick={() => setExpandedDistrict(expandedDistrict === dist.id ? null : dist.id)} className="p-3 bg-white shadow-sm text-slate-400 rounded-xl hover:text-[#2D9469]">
                       <ChevronDown className={`h-5 w-5 transition-transform duration-500 ${expandedDistrict === dist.id ? 'rotate-180' : ''}`} />
                    </button>
                    <button onClick={() => deleteDistrict(dist.id)} className="p-3 text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"><Trash2 className="h-4 w-4" /></button>
                 </div>

                 <div className="flex items-center gap-4 flex-row-reverse text-right flex-1">
                    <div className="bg-slate-100 p-3 rounded-2xl text-slate-400"><MapIcon className="h-5 w-5" /></div>
                    <div className="flex-1">
                       {editingDistrictId === dist.id ? (
                         <div className="flex gap-2 flex-row-reverse">
                            <input 
                              autoFocus
                              value={tempDistrictName}
                              onChange={e => setTempDistrictName(e.target.value)}
                              className="bg-white border-2 border-emerald-500 rounded-xl px-4 py-2 font-black text-sm text-right outline-none w-full"
                            />
                            <button onClick={() => saveDistrictName(dist.id)} className="bg-emerald-500 text-white p-2 rounded-xl"><Check className="h-4 w-4" /></button>
                            <button onClick={() => setEditingDistrictId(null)} className="bg-slate-200 text-slate-500 p-2 rounded-xl"><X className="h-4 w-4" /></button>
                         </div>
                       ) : (
                         <div className="flex items-center gap-2 justify-end group">
                            <button onClick={() => startEditDistrict(dist)} className="p-2 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-[#2D9469] transition-all"><Edit3 className="h-4 w-4" /></button>
                            <h4 className="font-black text-slate-900" onClick={() => setExpandedDistrict(expandedDistrict === dist.id ? null : dist.id)}>مركز {dist.name}</h4>
                         </div>
                       )}
                       <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{dist.villages?.length || 0} قرية مسجلة</p>
                    </div>
                 </div>
              </div>

              {expandedDistrict === dist.id && (
                <div className="p-6 border-t border-slate-100 space-y-6 animate-in slide-in-from-top duration-300">
                   {/* قائمة القرى */}
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {dist.villages?.map(v => (
                        <div key={v.id} className="bg-slate-50 p-4 rounded-2xl flex justify-between items-center flex-row-reverse group transition-all hover:bg-white hover:shadow-md border border-transparent hover:border-emerald-100">
                           {editingVillageId === v.id ? (
                             <div className="w-full space-y-2">
                                <input 
                                  value={tempVillageData?.name || ''} 
                                  onChange={e => setTempVillageData(prev => prev ? {...prev, name: e.target.value} : null)}
                                  className="w-full bg-white p-2 rounded-lg text-xs font-black text-right outline-none border border-emerald-300" 
                                />
                                <div className="flex gap-2">
                                   <input 
                                     type="number" 
                                     value={tempVillageData?.center.lat || 0} 
                                     onChange={e => setTempVillageData(prev => prev ? {...prev, center: {...prev.center, lat: Number(e.target.value)}} : null)}
                                     className="flex-1 bg-white p-2 rounded-lg text-[10px] text-center outline-none border border-slate-200" 
                                   />
                                   <input 
                                     type="number" 
                                     value={tempVillageData?.center.lng || 0} 
                                     onChange={e => setTempVillageData(prev => prev ? {...prev, center: {...prev.center, lng: Number(e.target.value)}} : null)}
                                     className="flex-1 bg-white p-2 rounded-lg text-[10px] text-center outline-none border border-slate-200" 
                                   />
                                </div>
                                <div className="flex gap-2 pt-1">
                                   <button onClick={() => saveVillageChanges(dist.id)} className="flex-1 bg-emerald-500 text-white py-2 rounded-lg text-[10px] font-black">حفظ</button>
                                   <button onClick={() => setEditingVillageId(null)} className="flex-1 bg-slate-200 text-slate-500 py-2 rounded-lg text-[10px] font-black">إلغاء</button>
                                </div>
                             </div>
                           ) : (
                             <>
                               <div className="text-right">
                                  <p className="font-black text-slate-800 text-xs">{v.name}</p>
                                  <p className="text-[8px] font-bold text-slate-400" dir="ltr">{v.center.lat.toFixed(4)}, {v.center.lng.toFixed(4)}</p>
                               </div>
                               <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                  <button onClick={() => startEditVillage(v)} className="p-2 text-slate-400 hover:text-emerald-500"><Edit3 className="h-4 w-4" /></button>
                                  <button onClick={() => removeVillage(dist.id, v.id)} className="p-2 text-rose-200 hover:text-rose-500"><Trash2 className="h-4 w-4" /></button>
                               </div>
                             </>
                           )}
                        </div>
                      ))}
                      {(!dist.villages || dist.villages.length === 0) && (
                        <p className="col-span-full text-center text-slate-300 text-[10px] py-4 font-bold">لا توجد قرى في هذا المركز</p>
                      )}
                   </div>

                   {/* إضافة قرية جديدة */}
                   <div className="bg-emerald-50/30 p-6 rounded-[2.5rem] border-2 border-emerald-50 space-y-4">
                      <div className="text-right mb-2 flex items-center justify-end gap-2">
                         <h5 className="text-[10px] font-black text-[#2D9469] uppercase tracking-widest">إضافة منطقة جديدة لمركز {dist.name}</h5>
                         <PlusCircle className="h-4 w-4 text-[#2D9469]" />
                      </div>
                      <div className="grid grid-cols-1 gap-3">
                         <input 
                           value={newVillageData.name} 
                           onChange={e => setNewVillageData({...newVillageData, name: e.target.value})} 
                           placeholder="اسم القرية" 
                           className="w-full bg-white p-4 rounded-xl text-xs font-black outline-none text-right shadow-sm border border-transparent focus:border-emerald-300" 
                         />
                         <div className="grid grid-cols-2 gap-2">
                            <div className="space-y-1">
                               <label className="text-[8px] font-bold text-slate-400 block text-center">خط العرض (Lat)</label>
                               <input 
                                 type="number" 
                                 value={newVillageData.lat} 
                                 onChange={e => setNewVillageData({...newVillageData, lat: Number(e.target.value)})} 
                                 className="w-full bg-white p-4 rounded-xl text-[10px] font-bold outline-none text-center shadow-sm" 
                               />
                            </div>
                            <div className="space-y-1">
                               <label className="text-[8px] font-bold text-slate-400 block text-center">خط الطول (Lng)</label>
                               <input 
                                 type="number" 
                                 value={newVillageData.lng} 
                                 onChange={e => setNewVillageData({...newVillageData, lng: Number(e.target.value)})} 
                                 className="w-full bg-white p-4 rounded-xl text-[10px] font-bold outline-none text-center shadow-sm" 
                               />
                            </div>
                         </div>
                      </div>
                      <button onClick={() => addVillage(dist.id)} className="w-full bg-[#2D9469] text-white py-4 rounded-2xl font-black text-xs shadow-lg active:scale-95 transition-all">إضافة القرية للقاعدة</button>
                   </div>
                </div>
              )}
           </div>
         ))}
