// --- مكون إدارة الإعلانات (Ad Manager) ---
const AdManager: React.FC = () => {
  const [ads, setAds] = useState<Ad[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [adData, setAdData] = useState<Partial<Ad>>({
    title: '', description: '', type: 'general', isActive: true, displayOrder: 0
  });
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const q = query(collection(db, "ads"), orderBy("displayOrder", "asc"));
    return onSnapshot(q, (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[];
      setAds(data.sort((a, b) => (a.displayOrder || 0) - (b.displayOrder || 0)));
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setAdData(prev => ({ ...prev, imageUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const saveAd = async () => {
    if (!adData.title || !adData.imageUrl) return alert('يرجى إكمال بيانات الإعلان');
    setLoading(true);
    try {
      const id = adData.id || `ad_${Date.now()}`;
      await setDoc(doc(db, "ads", id), {
        ...adData,
        id,
        views: adData.views || 0,
        clicks: adData.clicks || 0,
        createdAt: adData.createdAt || Date.now()
      });
      setIsAdding(false);
      setAdData({ title: '', description: '', type: 'general', isActive: true, displayOrder: 0 });
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  return (
    <div className="space-y-6 animate-reveal">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 flex justify-between items-center flex-row-reverse">
         <div className="text-right">
            <h3 className="text-xl font-black text-slate-900">إدارة الإعلانات</h3>
            <p className="text-[9px] font-bold text-slate-400 uppercase">الترويج والعروض الحصرية</p>
         </div>
         <button onClick={() => setIsAdding(!isAdding)} className="p-4 bg-emerald-600 text-white rounded-2xl shadow-lg active:scale-90 transition-all">
            {isAdding ? <X className="h-5 w-5" /> : <Plus className="h-5 w-5" />}
         </button>
      </div>

      {isAdding && (
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-50 space-y-6 animate-in zoom-in duration-300">
           <div 
             onClick={() => fileRef.current?.click()}
             className="w-full h-48 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-emerald-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden group transition-all"
           >
              {adData.imageUrl ? (
                <img src={adData.imageUrl} className="w-full h-full object-cover" />
              ) : (
                <>
                  <ImageIcon className="h-10 w-10 text-emerald-200 mb-2" />
                  <p className="text-[10px] font-black text-emerald-300 uppercase">ارفع صورة الإعلان</p>
                </>
              )}
           </div>
           <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

           <div className="space-y-4">
              <input value={adData.title} onChange={e => setAdData({...adData, title: e.target.value})} placeholder="عنوان الإعلان" className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right" />
              <textarea value={adData.description} onChange={e => setAdData({...adData, description: e.target.value})} placeholder="وصف العرض..." className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right min-h-[100px]" />

              <div className="grid grid-cols-2 gap-3">
                 <div className="bg-slate-50 p-4 rounded-2xl">
                    <label className="text-[8px] font-black text-slate-400 block mb-1">نوع الإعلان</label>
                    <select value={adData.type} onChange={e => setAdData({...adData, type: e.target.value as any})} className="w-full bg-transparent font-black text-xs outline-none text-right">
                       <option value="general">عام</option>
                       <option value="restaurant">مطعم</option>
                       <option value="service">خدمة</option>
                       <option value="special_offer">عرض خاص</option>
                    </select>
                 </div>
                 <div className="bg-slate-50 p-4 rounded-2xl">
                    <label className="text-[8px] font-black text-slate-400 block mb-1">الترتيب</label>
                    <input type="number" value={adData.displayOrder} onChange={e => setAdData({...adData, displayOrder: Number(e.target.value)})} className="w-full bg-transparent font-black text-xs outline-none text-center" />
                 </div>
              </div>
           </div>

           <button onClick={saveAd} disabled={loading} className="w-full bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg shadow-2xl active:scale-95 transition-all">
              {loading ? <Loader2 className="animate-spin h-6 w-6 mx-auto" /> : 'حفظ ونشر الإعلان'}
           </button>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4">
         {ads.map(ad => (
           <div key={ad.id} className="bg-white p-5 rounded-[2.5rem] border border-slate-50 shadow-sm space-y-4 relative overflow-hidden group">
              <div className="flex gap-4 flex-row-reverse">
                 <div className="w-24 h-24 rounded-2xl overflow-hidden shrink-0 shadow-md">
                    <img src={ad.imageUrl} className="w-full h-full object-cover" />
                 </div>
                 <div className="flex-1 text-right">
                    <h4 className="font-black text-slate-900 text-sm">{ad.title}</h4>
                    <p className="text-[10px] font-bold text-slate-400 line-clamp-2 mt-1">{ad.description}</p>
                    <div className="flex items-center gap-3 justify-end mt-2">
                       <span className="text-[8px] font-black bg-slate-100 text-slate-400 px-2 py-0.5 rounded-full">{ad.type}</span>
                       <div className={`w-1.5 h-1.5 rounded-full ${ad.isActive ? 'bg-emerald-500' : 'bg-slate-300'}`}></div>
                    </div>
                 </div>
              </div>

              <div className="flex justify-between items-center pt-3 border-t border-slate-50">
                 <div className="flex gap-4">
                    <div className="flex items-center gap-1.5">
                       <Eye className="h-3 w-3 text-slate-300" />
                       <span className="text-[10px] font-black text-slate-400">{ad.views}</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                       <MousePointer2 className="h-3 w-3 text-emerald-400" />
                       <span className="text-[10px] font-black text-emerald-600">{ad.clicks}</span>
                    </div>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => { setAdData(ad); setIsAdding(true); }} className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:text-emerald-600 transition-all"><Edit3 className="h-4 w-4" /></button>
                    <button onClick={async () => { if(confirm('حذف الإعلان؟')) await deleteDoc(doc(db, "ads", ad.id)); }} className="p-3 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 className="h-4 w-4" /></button>
                 </div>
              </div>
           </div>
         ))}
      </div>
    </div>
  );
};

// --- مكون إدارة المطاعم (Restaurant Manager) ---
const RestaurantManager: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [activeRestId, setActiveRestId] = useState<string | null>(null);

  const [restData, setRestData] = useState<Partial<Restaurant>>({ 
    name: '', category: 'مشويات', photoURL: '', menu: [], isOpen: true 
  });

  const [newItem, setNewItem] = useState({ name: '', price: 0, photoURL: '' });

  const photoRef = useRef<HTMLInputElement>(null);
  const itemPhotoRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImage = (e: React.ChangeEvent<HTMLInputElement>, target: 'REST' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      if (target === 'REST') setRestData(prev => ({ ...prev, photoURL: reader.result as string }));
      else setNewItem(prev => ({ ...prev, photoURL: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = restData.id || `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, address: 'المنوفية', lat: 30.5, lng: 31.0
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menu: [], isOpen: true });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
    await updateDoc(doc(db, "restaurants", rid), { menu });
    setNewItem({ name: '', price: 0, photoURL: '' });
  };

  return (
    <div className="space-y-6 animate-reveal">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 flex justify-between items-center flex-row-reverse">
         <div className="text-right">
            <h3 className="text-xl font-black text-slate-900">إدارة المطاعم</h3>
            <p className="text-[9px] font-bold text-slate-400 uppercase">قائمة الشركاء والمنيو</p>
         </div>
         <button onClick={() => setIsAdding(!isAdding)} className="p-4 bg-emerald-600 text-white rounded-2xl shadow-lg active:scale-90 transition-all">
            {isAdding ? <X className="h-5 w-5" /> : <Store className="h-5 w-5" />}
         </button>
      </div>

      {isAdding && (
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-50 space-y-6 animate-in zoom-in duration-300">
           <div 
             onClick={() => photoRef.current?.click()}
             className="w-full h-40 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-emerald-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden"
           >
              {restData.photoURL ? <img src={restData.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-10 w-10 text-emerald-200" />}
           </div>
           <input type="file" ref={photoRef} className="hidden" accept="image/*" onChange={e => handleImage(e, 'REST')} />

           <div className="space-y-4">
              <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} placeholder="اسم المطعم" className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right" />
              <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} placeholder="التصنيف (مثلاً: بيتزا، كريب)" className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right" />
           </div>

           <button onClick={saveRestaurant} disabled={loading} className="w-full bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg shadow-2xl active:scale-95 transition-all">
              {loading ? <Loader2 className="animate-spin h-6 w-6 mx-auto" /> : 'إضافة المطعم الآن'}
           </button>
        </div>
      )}

      <div className="grid grid-cols-1 gap-6">
         {restaurants.map(rest => (
           <div key={rest.id} className="bg-white p-6 rounded-[3rem] border border-slate-50 shadow-sm space-y-6">
              <div className="flex justify-between items-start flex-row-reverse">
