                    <div className="w-16 h-16 bg-slate-950 rounded-2xl overflow-hidden shadow-lg border-2 border-white shrink-0">
                       {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-4 text-emerald-400" />}
                    </div>
                    <div>
                       <h4 className="font-black text-slate-900 text-lg leading-tight">{rest.name}</h4>
                       <p className="text-[10px] font-bold text-emerald-600">{rest.category}</p>
