import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, OrderCategory } from '../types';
import { OrderStatus } from '../types';
import { MENOFIA_DATA } from '../config/constants';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, Map as MapIcon, User as UserIcon, Home, 
  ShieldAlert, StickyNote, Coffee, Pill, Bot, Zap, Car,
  Plus, Minus, Crosshair, Check, DollarSign, Building2,
  Camera, Eye, ZoomIn, Download, AlertTriangle, Users as UsersIcon,
  Info
} from 'lucide-react';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc, orderBy
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;

    // جلب الطلبات التي تنتظر عروض
    const unsubAvailable = onSnapshot(
      query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS), orderBy("createdAt", "desc")), 
      (snapshot) => {
        setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
      }
    );

    // جلب الطلب النشط حالياً الخاص بالكابتن
    const unsubActive = onSnapshot(
      query(collection(db, "orders"), where("driverId", "==", user.id)), 
      (snapshot) => {
        const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
        const current = all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status));
        setActiveOrder(current || null);
      }
    );

    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const handleSendOffer = async (order: Order) => {
    const price = parseFloat(offerPrice);
    if (!price || price <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      // التحقق مما إذا كان الكابتن قدم عرضاً مسبقاً (اختياري)
      await addDoc(collection(db, "offers"), {
        orderId: order.id,
        driverId: user.id,
        driverName: user.name,
        driverPhone: user.phone,
        driverRating: 5.0, // تقييم افتراضي أو جلب الحقيقي
        driverPhoto: user.photoURL || null,
        vehicleType: user.vehicleType || 'TOKTOK',
        price: price,
        createdAt: Date.now()
      });
      setShowOfferInput(null);
      setOfferPrice('');
      alert('تم إرسال عرضك بنجاح للعميل! بانتظار موافقته.');
    } catch (e) { alert('خطأ في إرسال العرض'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ في تحديث الحالة'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
     return (
       <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-10 text-center font-['Cairo']">
          <ShieldAlert className="h-20 w-20 text-emerald-600 animate-bounce mb-6" />
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter">حسابك قيد المراجعة</h2>
          <p className="text-slate-400 font-bold text-sm mt-2">سيتم تفعيل حسابك ككابتن في المنوفية خلال دقائق. يرجى الانتظار أو التواصل مع الإدارة.</p>
       </div>
     );
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50 px-6 space-y-6 pb-32 pt-8 animate-in fade-in overflow-y-auto no-scrollbar">
        <div className={`p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
           <div>
              <h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'نشط الآن' : 'متوقف'}</h2>
              <p className="text-[10px] font-black opacity-60 mt-2 uppercase tracking-widest">طلبات المنوفية بانتظارك</p>
           </div>
           <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}>
              <Power className="h-10 w-10" />
           </button>
        </div>

        {activeOrder ? (
           <div className="bg-white rounded-[4rem] shadow-2xl p-10 space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
              <div className="flex justify-between items-center">
                 <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
                 <p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-lg opacity-30 font-bold uppercase">ج.م</span></p>
              </div>
              <div className="space-y-8 text-right">
                 <div className="flex gap-6 items-start flex-row-reverse">
                    <div className="bg-slate-50 p-5 rounded-3xl text-emerald-600 shrink-0"><MapPin className="h-8 w-8" /></div>
                    <div className="flex-1">
                       <p className="helper-text uppercase mb-2 tracking-widest">مسار الرحلة المعتمد</p>
                       <p className="font-black text-2xl text-slate-950 leading-tight mb-4">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p>
                    </div>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4 pt-4">
                 <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /></a>
                 <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-50 text-slate-900 py-7 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-3 active:scale-95 transition-all"><MessageCircle className="h-7 w-7" /></button>
                 <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-all">
                    {isSubmitting ? <Loader2 className="h-10 w-10 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد استلام الطلب' : 'تأكيد التوصيل والتحصيل'}
                 </button>
              </div>
           </div>
        ) : (
           <div className="space-y-6">
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.4em] px-4 text-right">مشاوير جديدة متاحة ({availableOrders.length})</h3>

              {availableOrders.map(o => (
                 <div key={o.id} className="bg-white p-10 rounded-[4rem] border-2 border-slate-50 shadow-xl space-y-8 animate-reveal transition-all hover:border-emerald-500">
                    {showOfferInput === o.id ? (
                      <div className="space-y-8 animate-in zoom-in text-center">
                         <h4 className="text-xl font-black text-slate-800">تقديم عرضك الخاص</h4>
                         <div className="relative">
                            <input 
                              autoFocus 
                              type="number" 
                              value={offerPrice} 
                              onChange={e => setOfferPrice(e.target.value)} 
                              placeholder={o.price.toString()} 
                              className="w-full bg-slate-50 border-none rounded-3xl p-8 text-5xl font-black text-center outline-none focus:ring-4 focus:ring-emerald-500/10 text-emerald-600" 
                            />
                            <span className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300 font-black text-lg uppercase">ج.م</span>
                         </div>
                         <div className="flex gap-4">
                            <button onClick={() => setShowOfferInput(null)} className="flex-1 py-6 rounded-3xl font-black text-slate-400">إلغاء</button>
                            <button onClick={() => handleSendOffer(o)} disabled={isSubmitting || !offerPrice} className="flex-[2] bg-emerald-600 text-white py-6 rounded-3xl font-black shadow-xl flex items-center justify-center gap-3">
                               {isSubmitting ? <Loader2 className="h-6 w-6 animate-spin" /> : <><Check className="h-6 w-6" /> إرسال العرض</>}
                            </button>
                         </div>
                      </div>
                    ) : (
                      <>
                        <div className="flex justify-between items-start text-right flex-row-reverse">
                           <div className="space-y-2">
                              <p className="text-2xl font-black text-slate-950 leading-none">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p>
                              <div className="flex items-center gap-3 justify-end mt-3">
                                <span className="bg-emerald-50 text-emerald-600 px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-widest">{o.requestedVehicleType}</span>
                                <span className="bg-slate-100 text-slate-400 px-4 py-1 rounded-full text-[9px] font-black uppercase tracking-widest">مسافة {o.distance} كم</span>
                              </div>
                           </div>
                           <div className="bg-slate-950 text-emerald-400 p-6 rounded-[2rem] font-black text-3xl shadow-2xl shrink-0">
                              {o.price}
                           </div>
                        </div>
                        <button 
                          onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price.toString()); }} 
                          className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 hover:bg-slate-900"
                        >
                            <Zap className="h-6 w-6 text-emerald-400 animate-pulse" /> تقديم عرض سعر
                        </button>
                      </>
                    )}
                 </div>
              ))}

              {availableOrders.length === 0 && (
                 <div className="py-24 text-center text-slate-300 font-black border-4 border-dashed border-slate-100 rounded-[4rem] bg-white">
                    <Bot className="h-16 w-16 mx-auto mb-6 opacity-20" />
                    <p className="tracking-widest uppercase text-xs">بانتظار طلبات جديدة في المنوفية...</p>
                 </div>
              )}
           </div>
        )}

      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 p-8 flex justify-around items-center z-[200] shadow-[0_-20px_50px_rgba(0,0,0,0.12)]">
         {[
           {id: 'HOME', icon: <Home className="h-7 w-7" />, label: 'الرئيسية'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'سجلي'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-[1.5rem] transition-all ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>
                 {tab.icon}
