        </div>
      </div>
    </div>
  </div>
);

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [aiOpen, setAiOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  // FIX: Added missing showChat state
  const [showChat, setShowChat] = useState(false);

  // States for ride
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [rideVehicleType, setRideVehicleType] = useState<VehicleType>('TOKTOK');

  useEffect(() => {
    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      const current = all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status));
      setActiveOrder(current || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      const q = query(collection(db, "offers"), where("orderId", "==", activeOrder.id), orderBy("createdAt", "desc"));
      return onSnapshot(q, (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    } else {
      setIncomingOffers([]);
    }
  }, [activeOrder]);

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId,
        driverName: offer.driverName,
        driverPhone: offer.driverPhone,
        driverPhoto: offer.driverPhoto || null,
        price: offer.price, // تحديث السعر النهائي بناءً على عرض الكابتن
        status: OrderStatus.ACCEPTED,
        acceptedAt: Date.now()
      });
      // إرسال إشعار للكابتن المقبول
      await addDoc(collection(db, "notifications"), {
        userId: offer.driverId,
        title: 'تم قبول عرضك! 🎉',
        body: `العميل ${user.name} وافق على عرض السعر الخاص بك. توجه للاستلام الآن.`,
        type: 'SUCCESS',
        createdAt: Date.now(),
        read: false
      });
    } catch (e) { alert('فشل قبول العرض'); }
  };

  const handleCreateOrder = async () => {
    if (!pickupVillage || !dropoffVillage) return;
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const basePrice = pickupVillage.id === dropoffVillage.id ? DEFAULT_PRICING.sameVillagePrice : Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);

      await addDoc(collection(db, "orders"), {
        customerId: user.id,
        customerPhone: user.phone,
        category: 'TAXI',
        pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS,
        createdAt: Date.now(),
        requestedVehicleType: rideVehicleType,
        price: basePrice, // سعر استرشادي أولي
        distance: dist,
        paymentMethod: 'CASH'
      });
    } catch (e) { alert('خطأ في إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  // FIX: Added conditional rendering for ChatView
  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-slate-50">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-5 md:p-12 space-y-6 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">

          {!activeOrder ? (
            <div className="space-y-8 animate-reveal">
              <div className="flex items-center justify-between">
                 <div><h2 className="text-3xl font-black text-slate-950 tracking-tighter">وصلها المنوفية</h2><p className="text-slate-400 font-bold text-[10px] uppercase mt-1">اطلب الحين وكباتنا يردون عليك</p></div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-[1.5rem] active:scale-90 transition-all"><Bot className="h-6 w-6" /></button>
              </div>

              {/* واجهة اختيار المواقع (تم اختصارها هنا لغرض التركيز على المزايدة) */}
              <div className="space-y-4">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-2">حدد تفاصيل رحلتك</p>
                 <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
                    <div className="flex gap-4 items-start flex-row-reverse">
                       <div className="bg-emerald-50 p-3 rounded-xl text-emerald-600"><MapPin className="h-5 w-5" /></div>
                       <div className="flex-1">
                          <p className="text-[9px] font-black text-slate-400 uppercase mb-1">من أين؟</p>
                          <select 
                            onChange={(e) => {
                              const v = MENOFIA_DATA.flatMap(d => d.villages).find(vill => vill.id === e.target.value);
                              if(v) setPickupVillage(v);
                            }}
                            className="w-full bg-slate-50 p-4 rounded-2xl font-black text-sm outline-none text-right appearance-none"
                          >
                            <option>اختر نقطة الانطلاق</option>
                            {MENOFIA_DATA.flatMap(d => d.villages).map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
                          </select>
                       </div>
                    </div>
                    <div className="flex gap-4 items-start flex-row-reverse">
                       <div className="bg-rose-50 p-3 rounded-xl text-rose-600"><Check className="h-5 w-5" /></div>
                       <div className="flex-1">
                          <p className="text-[9px] font-black text-slate-400 uppercase mb-1">إلى أين؟</p>
                          <select 
                            onChange={(e) => {
                              const v = MENOFIA_DATA.flatMap(d => d.villages).find(vill => vill.id === e.target.value);
                              if(v) setDropoffVillage(v);
                            }}
                            className="w-full bg-slate-50 p-4 rounded-2xl font-black text-sm outline-none text-right appearance-none"
                          >
                            <option>اختر وجهة الوصول</option>
                            {MENOFIA_DATA.flatMap(d => d.villages).map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
                          </select>
                       </div>
                    </div>
                 </div>
              </div>

              <div className="grid grid-cols-3 gap-3">
                 {[
                   {id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-5 w-5" />},
                   {id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-5 w-5" />},
                   {id: 'CAR', label: 'سيارة', icon: <Car className="h-5 w-5" />}
                 ].map(v => (
                   <button key={v.id} onClick={() => setRideVehicleType(v.id as VehicleType)} className={`py-5 rounded-[1.8rem] flex flex-col items-center gap-2 border-2 transition-all ${rideVehicleType === v.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-transparent text-slate-300'}`}>
                      {v.icon}
                      <span className="text-[10px] font-black">{v.label}</span>
                   </button>
                 ))}
              </div>

              <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-slate-950 text-white py-8 rounded-[3rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
                 {isSubmitting ? <Loader2 className="h-8 w-8 animate-spin" /> : <><Navigation2 className="h-6 w-6 text-emerald-400" /> اطلب الحين</>}
              </button>
            </div>
          ) : (
            <div className="space-y-12 pb-20">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="animate-in zoom-in space-y-10">
                    <div className="text-center space-y-4">
                       <div className="relative py-10">
                          <div className="absolute inset-0 flex items-center justify-center">
                             <div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div>
                          </div>
                          <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block border-4 border-emerald-50">
                             <Timer className="h-20 w-20 text-emerald-600 animate-pulse" />
                          </div>
                       </div>
                       <h2 className="text-3xl font-black text-slate-900 tracking-tighter leading-tight">جاري استقبال عروض الكباتن...</h2>
                       <p className="text-xs font-bold text-slate-400 px-10 leading-relaxed">طلبك الآن يظهر لكل الكباتن النشطين في المنوفية. ستظهر لك عروض الأسعار هنا فوراً.</p>
                    </div>

                    <div className="space-y-4">
                       <div className="flex items-center justify-between px-4">
                          <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full animate-bounce">{incomingOffers.length} عرض متاح</span>
                          <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">العروض الحالية</h4>
