                    </div>

                    <button 
                      onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} 
                      className="w-full py-4 text-rose-500 font-black text-[10px] uppercase tracking-widest hover:underline"
                    >
                      إلغاء الطلب
                    </button>
                 </div>
               ) : activeOrder.status === OrderStatus.ACCEPTED ? (
                 <div className="animate-in slide-in-from-bottom duration-700 space-y-10">
                    <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl overflow-hidden relative">
                       <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 blur-3xl -mr-16 -mt-16"></div>
                       <div className="text-right relative z-10">
                          <p className="text-[10px] font-black opacity-60 uppercase mb-2">طلبك مقبول</p>
                          <h3 className="text-2xl font-black leading-tight">الكابتن في طريقه إليك</h3>
                       </div>
                       <div className="bg-white/20 p-5 rounded-full relative z-10"><Navigation2 className="h-8 w-8 animate-bounce" /></div>
                    </div>

                    <div className="flex flex-col items-center gap-6 text-center">
                       <div className="relative">
                          <div className="w-32 h-32 bg-white rounded-[3rem] shadow-2xl border-4 border-emerald-500 overflow-hidden">
                             {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-16 w-16 text-slate-200 mt-8 mx-auto" />}
                          </div>
                          <div className="absolute -bottom-2 -right-2 bg-emerald-500 p-2 rounded-2xl shadow-lg border-4 border-white"><ShieldCheck className="h-5 w-5 text-white" /></div>
                       </div>
                       <div>
                          <h4 className="text-3xl font-black text-slate-900 tracking-tight">{activeOrder.driverName}</h4>
                          <div className="flex items-center gap-2 justify-center mt-2">
                             <span className="bg-slate-100 text-slate-600 px-4 py-1.5 rounded-2xl text-[10px] font-black uppercase tracking-widest">{activeOrder.requestedVehicleType}</span>
                             <span className="text-emerald-600 font-black text-sm">السعر المتفق عليه: {activeOrder.price} ج.م</span>
                          </div>
                       </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                       {/* FIX: setShowChat is now defined */}
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 active:scale-95 transition-all"><MessageCircle className="h-7 w-7" /> محادثة</button>
                    </div>
                 </div>
               ) : null /* الحالات الأخرى مثل التوصيل تظل كما هي في كودك الأصلي */}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
