/**
 * وظيفة متقدمة لتطهير البيانات القادمة من Firestore من أي مراجع دائرية أو كائنات داخلية معقدة.
 * تضمن هذه الوظيفة أن الكائن الناتج هو JSON-safe تماماً عبر تصفية الكائنات غير البسيطة.
 */
export const stripFirestore = (data: any, seen = new WeakSet()): any => {
  // 1. التعامل مع القيم البدائية والقيم الفارغة
  if (data === null || data === undefined) return data;
  if (typeof data !== 'object') return data;

  // 2. منع التكرار الدائري (Circular Reference)
  if (seen.has(data)) return undefined;

  // 3. التعامل مع كائنات Firebase الخاصة (Timestamp)
  if (typeof data.toMillis === 'function') {
    return data.toMillis();
  }

  // 4. التعامل مع مراجع المستندات (DocumentReference)
  if (typeof data.path === 'string' && data.path.includes('/')) {
    return data.path;
  }

  // 5. التعامل مع التواريخ العادية
  if (data instanceof Date) {
    return data.getTime();
  }

  // 6. التحقق من أن الكائن هو "كائن بسيط" (Plain Object) أو مصفوفة
  // هذا الفحص ضروري لمنع الدخول في كائنات Firebase الداخلية مثل Q$1 أو Sa
  const isArray = Array.isArray(data);
  const isPlainObject = Object.getPrototypeOf(data) === Object.prototype || Object.getPrototypeOf(data) === null;

  if (!isArray && !isPlainObject) {
    // إذا كان كائناً معقداً (Class Instance) ليس من الأنواع المعروفة أعلاه، نرجعه كقيمة نصية أو نتجاهله
    return undefined;
  }

  // إضافة الكائن لمجموعة الكائنات التي تمت زيارتها
  seen.add(data);

  // 7. التعامل مع المصفوفات
  if (isArray) {
    return data
      .map(item => stripFirestore(item, seen))
      .filter(val => val !== undefined);
  }

  // 8. التعامل مع الكائنات البسيطة (Plain Objects)
  const stripped: any = {};
  let hasProperties = false;

  for (const key in data) {
    if (Object.prototype.hasOwnProperty.call(data, key)) {
      // تخطي الخصائص الداخلية التي تبدأ بـ _ أو $
      if (key.startsWith('_') || key.startsWith('$')) continue;

      const value = data[key];

      // تخطي الوظائف (Functions)
      if (typeof value === 'function') continue;

      const cleanedValue = stripFirestore(value, seen);
      if (cleanedValue !== undefined) {
        stripped[key] = cleanedValue;
        hasProperties = true;
      }
    }
  }

  return hasProperties ? stripped : (Object.keys(data).length === 0 ? {} : undefined);
};

/**
 * حساب المسافة بين نقطتين جغرافيتين بالكيلومتر (صيغة هافرسين)
 */
export const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  if (!lat1 || !lon1 || !lat2 || !lon2) return 0;
  const R = 6371; // نصف قطر الأرض بالكيلومتر
  const dLat = (lat2 - lat1) * (Math.PI / 180);
  const dLon = (lon2 - lon1) * (Math.PI / 180);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + 
            Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * 
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return parseFloat((R * c).toFixed(1));
};

