                   {MENOFIA_DATA.map(d => (
                     <button key={d.id} onClick={() => { onDistrictSelect(d); setIsDistOpen(false); }} className={`p-4 rounded-2xl font-black text-xs transition-all ${selectedDistrict?.id === d.id ? 'bg-emerald-600 text-white shadow-lg' : 'bg-slate-50 text-slate-600'}`}>
                        {d.name}
                     </button>
                   ))}
                </div>
             </div>
          </div>
       )}

       {/* Village Modal */}
       {isVillOpen && (
          <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-end justify-center p-4">
             <div className="bg-white w-full max-w-md rounded-[3rem] p-8 flex flex-col max-h-[70vh] animate-in slide-in-from-bottom duration-300">
                <div className="flex justify-between items-center mb-6 shrink-0">
                   <button onClick={() => setIsVillOpen(false)} className="p-2 text-slate-300 hover:text-slate-900"><X /></button>
                   <div className="text-right">
                      <h3 className="text-xl font-black">قرى مركز {selectedDistrict?.name}</h3>
                      <p className="text-[10px] font-bold text-slate-400">اختر وجهتك بدقة</p>
                   </div>
                </div>
                <div className="flex-1 overflow-y-auto no-scrollbar space-y-2">
                   {selectedDistrict?.villages.map(v => (
                     <button key={v.id} onClick={() => { onVillageSelect(v); setIsVillOpen(false); }} className={`w-full p-5 rounded-2xl font-black text-sm text-right flex items-center justify-between flex-row-reverse transition-all ${selectedVillage?.id === v.id ? 'bg-emerald-50 text-emerald-600 border border-emerald-200 shadow-sm' : 'bg-slate-50 text-slate-600'}`}>
                        {v.name}
                        {selectedVillage?.id === v.id && <Check className="h-4 w-4" />}
                     </button>
                   ))}
                </div>
             </div>
          </div>
       )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [expandedAd, setExpandedAd] = useState<Ad | null>(null);
  const [ads, setAds] = useState<Ad[]>([]);

  // States for Ride Order
  const [pickupDistrict, setPickupDistrict] = useState<District | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');

  const [dropoffDistrict, setDropoffDistrict] = useState<District | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [dropoffNotes, setDropoffNotes] = useState('');

  const [rideVehicleType, setRideVehicleType] = useState<VehicleType>('TOKTOK');

  // Pharmacy States
  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionImage, setPrescriptionImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [showChat, setShowChat] = useState(false);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');

  // 1. مراقبة المطاعم والطلبات النشطة والإعلانات
  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });

    onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });

    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      // الترتيب اليدوي لضمان الحصول على أحدث طلب دائماً
      const sorted = all.sort((a, b) => b.createdAt - a.createdAt);
      setActiveOrder(sorted.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  // 2. مراقبة العروض المرتبطة بالطلب النشط مع منطق تحسين التزامن
  useEffect(() => {
    if (activeOrder?.id && activeOrder.status === OrderStatus.WAITING_FOR_OFFERS) {
      const q = query(collection(db, "offers"), where("orderId", "==", activeOrder.id));

      const unsubscribe = onSnapshot(q, (snap) => {
        const fetched = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[];
        // تصفية وترتيب العروض يدوياً لتجنب مشاكل Firestore indexes
        setIncomingOffers(fetched.sort((a, b) => b.createdAt - a.createdAt));
      });

      return () => unsubscribe();
    } else {
      setIncomingOffers([]);
    }
  }, [activeOrder?.id, activeOrder?.status]);

  const approxRidePrice = useMemo(() => {
    if (!pickupVillage || !dropoffVillage) return 0;
    const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
    const multiplier = DEFAULT_PRICING.multipliers[rideVehicleType] || 1;
    if (pickupVillage.id === dropoffVillage.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multiplier), DEFAULT_PRICING.minPrice);
  }, [pickupVillage, dropoffVillage, rideVehicleType]);

  const handleCreateRideOrder = async () => {
    if(!pickupVillage || !dropoffVillage) return alert('يرجى اختيار الموقع والوجهة');
    setIsSubmitting(true);
    setIncomingOffers([]); // تصفير العروض للطلب الجديد
    try {
       const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
       await addDoc(collection(db, "orders"), {
          customerId: user.id, customerPhone: user.phone, category: 'TAXI',
          pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
          dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
          pickupNotes, dropoffNotes,
          status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: rideVehicleType, price: approxRidePrice, distance: dist,
          operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
       });

       const waMsg = `📢 *طلب مشوار جديد*\n📍 *من:* ${pickupVillage.name} (${pickupNotes})\n🏁 *إلى:* ${dropoffVillage.name} (${dropoffNotes})\n🛵 *المركبة:* ${rideVehicleType}\n💰 *السعر:* ${approxRidePrice} ج.م\n👤 *العميل:* ${user.name}\n📱 *الهاتف:* ${user.phone}`;
       window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent(waMsg)}`, '_blank');
    } catch(e) { alert('خطأ في إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, 
        driverName: offer.driverName, 
        driverPhone: offer.driverPhone,
        driverPhoto: offer.driverPhoto || null,
        price: offer.price,
        status: OrderStatus.ACCEPTED, 
        acceptedAt: Date.now()
      });
    } catch (e) { alert('فشل قبول العرض'); }
  };

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    setIsSubmitting(true);
    setIncomingOffers([]);
    try {
      const dist = calculateDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

      const orderData: Partial<Order> = {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        dropoffNotes,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: deliveryPrice + foodTotal, distance: dist, operatorId: 'main', zoneId: 'monofia',
        paymentMethod: 'CASH', foodItems: cart, restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name,
        pickupNotes: `طلب طعام من مطعم ${viewingRestaurant.name}`
      };
      await addDoc(collection(db, "orders"), orderData);
      setViewingRestaurant(null);
    } catch (e) { alert('خطأ فني'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}
      {expandedAd && <AdDetailModal ad={expandedAd} onClose={() => setExpandedAd(null)} onAction={(ad) => {
         if (ad.type === 'restaurant' && ad.targetId) {
            const rest = restaurants.find(r => r.id === ad.targetId);
            if (rest) setViewingRestaurant(rest);
         } else {
            window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent('أريد الاستفسار عن إعلان: ' + ad.title)}`, '_blank');
         }
      }} />}

      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-slate-50">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-10 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div>
                    <h2 className="text-4xl font-black text-slate-950 tracking-tighter">وصـــلــهــا المنوفية</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">خدمة التوصيل الأذكى بالمحافظة</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl active:scale-90 shadow-sm border-none transition-all">
                    <Bot className="h-8 w-8" />
                 </button>
              </div>

              {/* Ads Carousel */}
              {ads.length > 0 && (
                <div className="flex gap-4 overflow-x-auto no-scrollbar py-2 -mx-2 px-2 scroll-smooth">
                   {ads.filter(ad => ad.isActive).map(ad => (
                     <div key={ad.id} onClick={() => setExpandedAd(ad)} className="min-w-[85%] md:min-w-[60%] aspect-video bg-slate-900 rounded-[2.5rem] overflow-hidden relative shadow-xl cursor-pointer group active:scale-95 transition-all">
                        <img src={ad.imageUrl} className="w-full h-full object-cover opacity-80 group-hover:scale-110 transition-transform duration-700" alt={ad.title} />
                        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-transparent flex flex-col justify-end p-6">
                           <h4 className="text-white font-black text-lg leading-tight mb-1">{ad.title}</h4>
                           <p className="text-emerald-400 text-[10px] font-bold uppercase flex items-center gap-2">
                              <Sparkles className="h-3 w-3" /> عرض حصري
                           </p>
                        </div>
                     </div>
                   ))}
                </div>
              )}

              <div className="grid grid-cols-3 gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'طعام', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'أدوية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-8 w-8" }) : cat.icon}
                       <span className="text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'TAXI' && (
                <div className="space-y-8 animate-in slide-in-from-right">
                   <div className="space-y-6">
                      <LocationSelector 
                        label="نقطة الانطلاق" helper="من أين ستبدأ رحلتك؟" icon={<MapPin />} iconBg="bg-emerald-500"
                        selectedDistrict={pickupDistrict} selectedVillage={pickupVillage} notes={pickupNotes}
                        onDistrictSelect={setPickupDistrict} onVillageSelect={setPickupVillage} onNotesChange={setPickupNotes}
                      />
                      <LocationSelector 
                        label="وجهة الوصول" helper="إلى أين تريد الذهاب؟" icon={<Check />} iconBg="bg-rose-500"
                        selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes}
                        onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes}
                      />
                   </div>

                   <div className="grid grid-cols-3 gap-3">
                      {[
                        {id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-5 w-5" />},
                        {id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-5 w-5" />},
                        {id: 'CAR', label: 'سيارة', icon: <Car className="h-5 w-5" />}
                      ].map(v => (
                        <button key={v.id} onClick={() => setRideVehicleType(v.id as VehicleType)} className={`py-6 rounded-[2rem] flex flex-col items-center gap-2 border-2 transition-all ${rideVehicleType === v.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-transparent text-slate-300'}`}>
                           {v.icon}
                           <span className="text-[10px] font-black">{v.label}</span>
                        </button>
                      ))}
