// --- Restaurant Menu ---
const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       <div className="bg-slate-900 p-6 pt-12 text-white flex justify-between items-center shadow-xl shrink-0">
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl active:scale-90 transition-all"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right">
             <h3 className="text-xl font-black">{restaurant.name}</h3>
             <p className="text-[10px] font-bold text-emerald-400">{restaurant.category}</p>
          </div>
       </div>
       <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 no-scrollbar">
          {restaurant.menu?.map(item => (
            <div key={item.id} className="bg-white p-4 rounded-[2rem] shadow-sm border-2 border-slate-100 flex justify-between items-center">
               <div className="flex items-center gap-3">
                  <div className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-xl">
                     <button onClick={() => addToCart(item)} className="p-1.5 bg-emerald-500 text-white rounded-lg active:scale-75"><Plus className="h-4 w-4" /></button>
                     <span className="font-black text-sm w-4 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                     <button onClick={() => removeFromCart(item.id)} className="p-1.5 bg-rose-50 text-rose-500 rounded-lg active:scale-75"><Minus className="h-4 w-4" /></button>
                  </div>
                  <p className="font-black text-emerald-600 text-xs">{item.price} ج.م</p>
               </div>
               <div className="text-right flex items-center gap-3 flex-row-reverse">
                  <div className="w-12 h-12 bg-slate-100 rounded-xl overflow-hidden shrink-0">
                     {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-3 text-slate-200" />}
                  </div>
                  <p className="font-black text-slate-800 text-sm">{item.name}</p>
               </div>
            </div>
          ))}
       </div>
       {cart.length > 0 && (
         <div className="p-6 bg-white border-t border-slate-100 pb-10 shadow-2xl shrink-0">
            <div className="flex justify-between items-center mb-4">
               <p className="text-xl font-black text-slate-900">{total} ج.م</p>
               <p className="text-[10px] font-black text-slate-400">الإجمالي</p>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-5 rounded-[1.8rem] font-black shadow-xl flex items-center justify-center gap-3">
               تأكيد الطلب
            </button>
         </div>
       )}
    </div>
  );
};

