      await addDoc(collection(db, "orders"), orderData);

      const waMsg = `💊 *طلب صيدلية جديد*\n📍 *التوصيل إلى:* ${dropoffVillage.name} (${dropoffNotes})\n📝 *الطلبات:* ${pharmacyNotes || 'مرفق صورة روشتة'}\n👤 *العميل:* ${user.name}\n📱 *الهاتف:* ${user.phone}`;
      window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent(waMsg)}`, '_blank');

      setPharmacyNotes('');
      setPrescriptionImage(null);
    } catch (e) {
      alert('خطأ في إرسال طلب الصيدلية');
    } finally {
      setIsSubmitting(false);
    }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}
      {expandedAd && <AdDetailModal ad={expandedAd} onClose={() => setExpandedAd(null)} onAction={(ad) => {
         if (ad.type === 'restaurant' && ad.targetId) {
            const rest = restaurants.find(r => r.id === ad.targetId);
            if (rest) setViewingRestaurant(rest);
         } else {
            window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent('أريد الاستفسار عن إعلان: ' + ad.title)}`, '_blank');
         }
      }} />}

      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-slate-50">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-10 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div>
                    <h2 className="text-4xl font-black text-slate-950 tracking-tighter">وصـــلــهــا المنوفية</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">خدمة التوصيل الأذكى بالمحافظة</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl active:scale-90 shadow-sm border-none transition-all">
                    <Bot className="h-8 w-8" />
                 </button>
              </div>

              {/* Ads Carousel */}
              {ads.length > 0 && (
                <div className="flex gap-4 overflow-x-auto no-scrollbar py-2 -mx-2 px-2 scroll-smooth">
                   {ads.filter(ad => ad.isActive).map(ad => (
                     <div key={ad.id} onClick={() => setExpandedAd(ad)} className="min-w-[85%] md:min-w-[60%] aspect-video bg-slate-900 rounded-[2.5rem] overflow-hidden relative shadow-xl cursor-pointer group active:scale-95 transition-all">
                        <img src={ad.imageUrl} className="w-full h-full object-cover opacity-80 group-hover:scale-110 transition-transform duration-700" alt={ad.title} />
                        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-transparent flex flex-col justify-end p-6">
                           <h4 className="text-white font-black text-lg leading-tight mb-1">{ad.title}</h4>
                           <p className="text-emerald-400 text-[10px] font-bold uppercase flex items-center gap-2">
                              <Sparkles className="h-3 w-3" /> عرض حصري
                           </p>
                        </div>
                     </div>
                   ))}
                </div>
              )}

              <div className="grid grid-cols-3 gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'طعام', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'أدوية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-8 w-8" }) : cat.icon}
                       <span className="text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'TAXI' && (
                <div className="space-y-8 animate-in slide-in-from-right">
                   <div className="space-y-6">
                      <LocationSelector 
                        label="نقطة الانطلاق" helper="من أين ستبدأ رحلتك؟" icon={<MapPin />} iconBg="bg-emerald-500"
                        selectedDistrict={pickupDistrict} selectedVillage={pickupVillage} notes={pickupNotes}
                        onDistrictSelect={setPickupDistrict} onVillageSelect={setPickupVillage} onNotesChange={setPickupNotes}
                      />
                      <LocationSelector 
                        label="وجهة الوصول" helper="إلى أين تريد الذهاب؟" icon={<Check />} iconBg="bg-rose-500"
                        selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes}
                        onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes}
                      />
                   </div>

                   <div className="grid grid-cols-3 gap-3">
                      {[
                        {id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-5 w-5" />},
                        {id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-5 w-5" />},
                        {id: 'CAR', label: 'سيارة', icon: <Car className="h-5 w-5" />}
                      ].map(v => (
                        <button key={v.id} onClick={() => setRideVehicleType(v.id as VehicleType)} className={`py-6 rounded-[2rem] flex flex-col items-center gap-2 border-2 transition-all ${rideVehicleType === v.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-transparent text-slate-300'}`}>
                           {v.icon}
                           <span className="text-[10px] font-black">{v.label}</span>
                        </button>
                      ))}
                   </div>

                   <div className="bg-slate-950 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl relative overflow-hidden group">
                      <div className="absolute top-0 right-0 w-32 h-full bg-emerald-500/10 blur-3xl"></div>
                      <div className="text-right z-10">
                         <p className="text-[10px] font-black text-emerald-400 uppercase mb-1">السعر التقريبي</p>
                         <h3 className="text-4xl font-black">{approxRidePrice} <span className="text-xs opacity-40 font-bold uppercase">ج.م</span></h3>
                      </div>
                      <button onClick={handleCreateRideOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="bg-emerald-600 text-white px-8 py-5 rounded-[1.8rem] font-black shadow-xl active:scale-95 transition-all z-10 hover:bg-emerald-500">
                         {isSubmitting ? <Loader2 className="animate-spin" /> : 'اطلب الحين'}
                      </button>
                   </div>
                </div>
              )}

              {selectedCategory === 'FOOD' && (
                <div className="space-y-8 animate-in zoom-in">
                   <LocationSelector 
                      label="عنوان التوصيل" helper="أين ستستلم طلب الطعام؟" icon={<Building2 />} iconBg="bg-rose-500"
                      selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes}
                      onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes}
                   />

                   {/* ميزة المطعم غير الموجود */}
                   <div className="bg-white p-6 rounded-[2.5rem] border-4 border-dashed border-emerald-100 space-y-4">
                      <div className="flex justify-between items-center flex-row-reverse" onClick={() => setShowManualFood(!showManualFood)}>
                         <div className="text-right">
                            <h4 className="font-black text-slate-800 text-sm">مطعمك مش في القائمة؟</h4>
                            <p className="text-[10px] font-bold text-slate-400">اكتب اسم المطعم والوجبة اللي محتاجها وهنجيبها لك</p>
                         </div>
                         <button className={`p-3 rounded-xl transition-all ${showManualFood ? 'bg-rose-50 text-rose-500' : 'bg-emerald-50 text-emerald-600'}`}>
                            {showManualFood ? <X className="h-4 w-4" /> : <Edit3 className="h-4 w-4" />}
                         </button>
                      </div>

                      {showManualFood && (
                        <div className="space-y-4 pt-2 animate-in slide-in-from-top duration-300">
                           <input 
                             value={manualRestName} onChange={e => setManualRestName(e.target.value)}
                             placeholder="اسم المطعم (مثلاً: مطعم الحبايب)"
                             className="w-full bg-slate-50 rounded-2xl py-4 px-6 text-xs font-bold outline-none border border-transparent focus:border-emerald-500 text-right"
                           />
                           <textarea 
                             value={manualMeal} onChange={e => setManualMeal(e.target.value)}
                             placeholder="الوجبة المطلوبة (مثلاً: ٢ كريب دجاج كبير)"
                             className="w-full bg-slate-50 rounded-2xl p-6 text-xs font-bold outline-none border border-transparent focus:border-emerald-500 text-right min-h-[100px]"
                           />
                           <button onClick={handleCreateManualFoodOrder} disabled={isSubmitting || !dropoffVillage} className="w-full bg-emerald-600 text-white py-5 rounded-[1.8rem] font-black text-sm shadow-xl active:scale-95 transition-all">
                              {isSubmitting ? <Loader2 className="animate-spin h-5 w-5 mx-auto" /> : 'اطلب الحين'}
                           </button>
                        </div>
                      )}
                   </div>

                   <div className="grid grid-cols-1 gap-6 pb-10">
                      <div className="flex items-center justify-between px-2 mb-2">
                         <h4 className="text-xl font-black text-slate-800">أشهر مطاعم المنوفية</h4>
                         <Store className="h-5 w-5 text-slate-300" />
                      </div>
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-6 rounded-[3rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group active:scale-98">
                           <div className="flex items-center gap-5 flex-row-reverse text-right">
                              <div className="w-16 h-16 bg-slate-900 rounded-[1.8rem] flex items-center justify-center overflow-hidden border border-white/10 shadow-lg">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-4 text-emerald-400" />}
                              </div>
                              <div>
                                 <h4 className="text-lg font-black text-slate-800 group-hover:text-emerald-600 transition-colors leading-tight">{rest.name}</h4>
                                 <p className="text-[10px] font-bold text-slate-400">{rest.category}</p>
                              </div>
                           </div>
                           <ChevronLeft className="h-6 w-6 text-slate-300 transition-transform group-hover:-translate-x-2" />
                        </div>
                      ))}
                   </div>
                </div>
              )}

              {selectedCategory === 'PHARMACY' && (
                <div className="space-y-8 animate-in slide-in-from-left">
                   <LocationSelector 
                      label="مكان استلام الدواء" helper="سيوصل الكابتن الأدوية لهذا الموقع" icon={<MapPin />} iconBg="bg-emerald-500"
                      selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes}
                      onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes}
                   />

                   <div className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-sm space-y-6">
                      <div className="text-right">
                         <h4 className="font-black text-slate-800 flex items-center gap-3 flex-row-reverse"><Pill className="text-emerald-500 h-5 w-5" /> تفاصيل الطلب</h4>
                         <p className="text-[10px] font-bold text-slate-400 mt-1">اكتب أسماء الأدوية المطلوبة أو ارفع صورة الروشتة</p>
                      </div>

                      <textarea 
                        value={pharmacyNotes} onChange={e => setPharmacyNotes(e.target.value)}
                        placeholder="مثال: علبة بنادول، شريط أدول، علبة مناديل..."
                        className="w-full bg-slate-50 rounded-[2rem] p-6 font-bold text-sm outline-none border-2 border-transparent focus:border-emerald-500 min-h-[120px] text-right transition-all shadow-inner"
                      />

                      <div 
                        onClick={() => fileInputRef.current?.click()}
                        className={`w-full h-40 rounded-[2rem] border-4 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all ${prescriptionImage ? 'border-emerald-500 bg-emerald-50/50' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}
                      >
                         {prescriptionImage ? (
                           <div className="relative w-full h-full">
                              <img src={prescriptionImage} className="w-full h-full object-contain rounded-[1.5rem]" />
                              <button onClick={(e) => { e.stopPropagation(); setPrescriptionImage(null); }} className="absolute top-2 right-2 bg-rose-500 text-white p-2 rounded-full shadow-lg"><X className="h-4 w-4" /></button>
                           </div>
                         ) : (
                           <>
                             <Camera className="h-10 w-10 text-slate-300 mb-2" />
                             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إرفاق صورة الروشتة</p>
                           </>
                         )}
                         <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
                            const file = e.target.files?.[0];
                            if (file) {
                               const reader = new FileReader();
                               reader.onloadend = () => setPrescriptionImage(reader.result as string);
                               reader.readAsDataURL(file);
                            }
                         }} />
                      </div>

                      <button onClick={handleCreatePharmacyOrder} disabled={isSubmitting || !dropoffVillage} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
                         {isSubmitting ? <Loader2 className="animate-spin h-6 w-6" /> : <><Navigation2 className="h-6 w-6 text-emerald-400" /> اطلب الأدوية الحين</>}
                      </button>
                   </div>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-12">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="animate-in zoom-in space-y-12">
                    <div className="text-center space-y-6">
                       <div className="relative py-10">
                          <div className="absolute inset-0 flex items-center justify-center">
                             <div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div>
                          </div>
                          <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block border-4 border-emerald-50">
                             <Timer className="h-24 w-24 text-emerald-600 animate-pulse" />
                          </div>
                       </div>
                       <h2 className="text-3xl font-black text-slate-950 tracking-tighter leading-tight">جاري استقبال عروض الكباتن...</h2>
                       <p className="text-xs font-bold text-slate-400 px-10 leading-relaxed">طلبك يظهر الآن لكافة الكباتن المعتمدين في المنوفية. ستظهر العروض هنا فور إرسالها.</p>
                    </div>

                    <div className="space-y-4">
                       <div className="flex items-center justify-between px-4 flex-row-reverse">
                          <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">العروض الحالية ({incomingOffers.length})</h4>
                          <div className="h-px flex-1 bg-slate-100 mr-4"></div>
                       </div>

                       <div className="space-y-4">
                          {incomingOffers.map(offer => (
                            <div key={offer.id} className="bg-white p-8 rounded-[3rem] border-4 border-slate-50 shadow-xl flex justify-between items-center hover:border-emerald-500 transition-all animate-in slide-in-from-bottom group">
                               <div className="text-center space-y-2">
                                  <p className="text-3xl font-black text-emerald-700 tracking-tight">{offer.price} <span className="text-[10px] opacity-40 uppercase">ج.م</span></p>
                                  <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2.5 rounded-2xl font-black text-xs shadow-lg shadow-emerald-100 active:scale-90 transition-all group-hover:bg-slate-950">قبول العرض</button>
                               </div>
                               <div className="flex items-center gap-5 flex-row-reverse text-right">
                                  <div className="w-16 h-16 bg-slate-900 text-emerald-400 rounded-2xl flex items-center justify-center overflow-hidden border border-white shadow-md">
                                    {offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-8 w-8" />}
                                  </div>
                                  <div>
                                     <p className="font-black text-slate-900 text-lg leading-tight">{offer.driverName}</p>
                                     <div className="flex items-center gap-2 justify-end mt-1.5">
                                        <span className="text-[10px] font-black text-amber-500 bg-amber-50 px-3 py-1 rounded-full flex items-center gap-1.5 shadow-sm">
                                           {offer.driverRating} <Star className="h-3 w-3 fill-amber-400" />
                                        </span>
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{offer.vehicleType === 'TOKTOK' ? 'توكتوك' : 'موتوسيكل'}</span>
                                     </div>
                                  </div>
                               </div>
                            </div>
                          ))}
                          {incomingOffers.length === 0 && (
                            <div className="py-24 text-center border-4 border-dashed border-slate-100 rounded-[3rem] bg-white/50 opacity-60">
                               <Loader2 className="h-8 w-8 animate-spin mx-auto text-slate-200 mb-4" />
                               <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">بانتظار أول كابتن...</p>
                            </div>
                          )}
                       </div>
                    </div>

                    <button onClick={async () => {
                       if(confirm('هل تريد إلغاء الطلب حقاً؟')) {
                          await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED });
                       }
                    }} className="w-full py-4 text-rose-500 font-black text-[10px] uppercase tracking-[0.4em] hover:bg-rose-50 rounded-2xl transition-all">إلغاء الطلب الحالي</button>
                 </div>
               ) : activeOrder.status === OrderStatus.DELIVERED ? (
                 <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                    <PartyPopper className="h-20 w-20 text-emerald-500 mx-auto animate-bounce" />
                    <h2 className="text-3xl font-black text-slate-950">وصلت بالسلامة!</h2>
                    <div className="bg-slate-50 p-8 rounded-[3rem] space-y-8">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">قيم تجربة التوصيل</p>
                       <div className="flex justify-center gap-3">
                          {[1,2,3,4,5].map(s => (
                            <button key={s} onClick={() => setRating(s)} className="transition-all active:scale-75 border-none bg-transparent outline-none"><Star className={`h-12 w-12 ${rating >= s ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} /></button>
                          ))}
                       </div>
                       <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="رأيك يهمنا لتطوير وصلها..." className="w-full bg-white border-2 border-slate-100 rounded-[2rem] p-6 font-bold text-sm outline-none text-right shadow-inner" dir="rtl" />
                    </div>
                    <button onClick={async () => {
                      await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.DELIVERED_RATED, rating, feedback: feedback.trim(), ratedAt: Date.now() });
                      setFeedback('');
                    }} className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl">تأكيد التقييم <ThumbsUp className="h-8 w-8 inline mr-2" /></button>
                 </div> // Fixed missing closing div
               ) : (
                 <div className="animate-in zoom-in space-y-12">
                    <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                       <div className="text-right">
                          <p className="text-[11px] font-black opacity-60 uppercase mb-2">تتبع الرحلة</p>
                          <h3 className="text-2xl font-black leading-none">الكابتن في طريقه إليك</h3>
                       </div>
                       <div className="bg-white/20 p-5 rounded-full"><Navigation2 className="h-8 w-8 animate-bounce" /></div>
                    </div>

                    <div className="flex flex-col items-center gap-6">
                       <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden">
                         {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                       </div>
                       <div className="text-center">
                          <h4 className="text-3xl font-black text-slate-950 tracking-tight">{activeOrder.driverName}</h4>
                          <p className="label-strong mt-2 uppercase text-emerald-600 bg-emerald-50 px-6 py-2 rounded-full inline-block">كابتن معتمد • المنوفية</p>
                       </div>
                    </div>

                    <div className="grid grid-cols-2 gap-5">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95"><PhoneCall className="h-7 w-7" /> اتصال</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 active:scale-95"><MessageCircle className="h-7 w-7" /> محادثة</button>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all border-none bg-transparent ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

export type UserRole = 'ADMIN' | 'OPERATOR' | 'DRIVER' | 'CUSTOMER';
export type UserStatus = 'PENDING_APPROVAL' | 'APPROVED' | 'SUSPENDED';
export type PaymentMethod = 'CASH' | 'WALLET';
export type VehicleType = 'TOKTOK' | 'MOTORCYCLE' | 'CAR';
export type OrderCategory = 'TAXI' | 'FOOD' | 'PHARMACY' | 'GROCERY' | 'PARCEL';

export enum OrderStatus {
  PENDING = 'PENDING',
  WAITING_FOR_OFFERS = 'WAITING_FOR_OFFERS',
  ACCEPTED = 'ACCEPTED',
  PICKED_UP = 'PICKED_UP',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  DELIVERED_RATED = 'DELIVERED_RATED',
  CANCELLED = 'CANCELLED'
}

export interface Ad {
  id: string;
  title: string;
  description: string;
  imageUrl: string;
  ctaText: string; // نص الزر مثل "اطلب الآن"
  type: 'special_offer' | 'restaurant' | 'service' | 'general';
  targetId?: string; // ID المطعم أو الخدمة المرتبطة
  targetCategory?: OrderCategory;
  isActive: boolean;
  displayOrder: number;
  views: number;
  clicks: number;
  createdAt: number;
}

export interface MenuItem {
  id: string;
  name: string;
  price: number;
  description?: string;
  photoURL?: string;
}

export interface Restaurant {
  id: string;
  name: string;
  category: string;
  address: string;
  lat: number;
  lng: number;
  photoURL?: string;
  menuImageURL?: string;
  menu: MenuItem[];
  isOpen: boolean;
  isFeatured?: boolean;
  promoText?: string;
}

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

export interface Offer {
  id: string;
  orderId: string;
  driverId: string;
  driverName: string;
  driverPhone: string;
  driverRating: number;
  driverPhoto?: string;
  vehicleType: VehicleType;
  price: number;
  createdAt: number;
}

export interface Village {
  id: string;
  name: string;
  center: { lat: number, lng: number };
}

export interface District {
  id: string;
  name: string;
  villages: Village[];
}

export interface User {
  id: string;
  email: string;
  phone: string;
  name: string;
  role: UserRole;
  status: UserStatus;
  photoURL?: string;
  vehicleType?: VehicleType;
  zoneId?: string;
  wallet: {
    balance: number;
    totalEarnings: number;
    withdrawn: number;
  };
}

export interface Order {
  id: string;
  customerId: string;
  customerPhone: string;
  driverId?: string;
  driverName?: string;
  driverPhone?: string;
  category: OrderCategory;
  pickup: { address: string; lat: number; lng: number; villageName?: string };
  dropoff: { address: string; lat: number; lng: number; villageName?: string };
  status: OrderStatus;
  price: number;
  distance: number;
  createdAt: number;
  paymentMethod: PaymentMethod;
  requestedVehicleType: VehicleType;
  foodItems?: CartItem[];
  restaurantId?: string;
  restaurantName?: string;
  pickupNotes?: string;
  dropoffNotes?: string;
  passengerCount?: number;
  prescriptionImage?: string;
  notes?: string;
  rating?: number;
  feedback?: string;
}

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Restaurant, MenuItem, Ad, OrderCategory, District } from '../types';
import { OrderStatus, UserStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Constants
import { DEFAULT_PRICING, MENOFIA_DATA } from '../config/constants';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, doc, onSnapshot, orderBy, 
  setDoc, addDoc, deleteDoc, updateDoc, limit, getDoc, where, increment
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  User as UserIcon, DollarSign, Bike, Search, Car, 
  ShieldCheck, Megaphone, Trash2, Save, Loader2, MessageCircle, 
  Calculator, TrendingUp, ChevronRight, MapPin, 
  LayoutDashboard, Send, Users2, Plus, X, Building2, UtensilsCrossed,
  Image as ImageIcon, PlusCircle, Camera, FileText, Edit3, Wallet,
  ShieldAlert, ChevronLeft, Eye, MousePointer2, Settings2, Flame,
  Store, CheckCircle2, Circle, Key, Hash, Mail, Fingerprint,
  Zap, Building, Map as MapIcon, ChevronDown, Globe, Check
} from 'lucide-react';

// --- مكون إدارة المراكز والقرى (Village & District Manager) ---
const VillageDistrictManager: React.FC = () => {
  const [districts, setDistricts] = useState<District[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAddingDistrict, setIsAddingDistrict] = useState(false);
  const [newDistrictName, setNewDistrictName] = useState('');
  const [expandedDistrict, setExpandedDistrict] = useState<string | null>(null);
  const [newVillageData, setNewVillageData] = useState({ name: '', lat: 30.5, lng: 31.0 });

  // حالات التعديل الجديدة
  const [editingDistrictId, setEditingDistrictId] = useState<string | null>(null);
  const [tempDistrictName, setTempDistrictName] = useState('');
  const [editingVillageId, setEditingVillageId] = useState<string | null>(null);
  const [tempVillageData, setTempVillageData] = useState<Village | null>(null);

  useEffect(() => {
    const q = query(collection(db, "districts"), orderBy("name", "asc"));
    return onSnapshot(q, (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[];
      setDistricts(data);
      setLoading(false);
    });
  }, []);

  const addDistrict = async () => {
    if (!newDistrictName.trim()) return;
    try {
      const id = `dist_${Date.now()}`;
      await setDoc(doc(db, "districts", id), {
        id,
        name: newDistrictName.trim(),
        villages: []
      });
      setNewDistrictName('');
      setIsAddingDistrict(false);
    } catch (e) { alert('خطأ في إضافة المركز'); }
  };

  const deleteDistrict = async (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المركز وكافة القرى التابعة له؟')) {
      await deleteDoc(doc(db, "districts", id));
    }
  };

  const startEditDistrict = (dist: District) => {
    setEditingDistrictId(dist.id);
    setTempDistrictName(dist.name);
  };

  const saveDistrictName = async (id: string) => {
    if (!tempDistrictName.trim()) return;
    try {
      await updateDoc(doc(db, "districts", id), { name: tempDistrictName.trim() });
      setEditingDistrictId(null);
    } catch (e) { alert('خطأ في التحديث'); }
  };

  const addVillage = async (districtId: string) => {
    if (!newVillageData.name.trim()) return;
    const district = districts.find(d => d.id === districtId);
    if (!district) return;

    try {
      const newVillage: Village = {
        id: `vill_${Date.now()}`,
        name: newVillageData.name.trim(),
        center: { lat: Number(newVillageData.lat), lng: Number(newVillageData.lng) }
      };

      const updatedVillages = [...(district.villages || []), newVillage];
      await updateDoc(doc(db, "districts", districtId), {
        villages: updatedVillages
      });
      setNewVillageData({ name: '', lat: 30.5, lng: 31.0 });
    } catch (e) { alert('خطأ في إضافة القرية'); }
  };

  const removeVillage = async (districtId: string, villageId: string) => {
    const district = districts.find(d => d.id === districtId);
    if (!district) return;
    if (!confirm('حذف هذه القرية؟')) return;

    try {
      const updatedVillages = district.villages.filter(v => v.id !== villageId);
      await updateDoc(doc(db, "districts", districtId), {
        villages: updatedVillages
      });
    } catch (e) { alert('خطأ في حذف القرية'); }
  };

  const startEditVillage = (vill: Village) => {
    setEditingVillageId(vill.id);
    setTempVillageData({ ...vill });
  };

  const saveVillageChanges = async (districtId: string) => {
    if (!tempVillageData || !tempVillageData.name.trim()) return;
    const district = districts.find(d => d.id === districtId);
    if (!district) return;

    try {
      const updatedVillages = district.villages.map(v => 
        v.id === tempVillageData.id ? tempVillageData : v
      );
      await updateDoc(doc(db, "districts", districtId), { villages: updatedVillages });
      setEditingVillageId(null);
      setTempVillageData(null);
    } catch (e) { alert('خطأ في حفظ بيانات القرية'); }
  };

  return (
    <div className="space-y-6 animate-reveal">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 flex justify-between items-center flex-row-reverse">
         <div className="text-right">
            <h3 className="text-xl font-black text-slate-900">إدارة جغرافيا المنوفية</h3>
            <p className="text-[9px] font-bold text-slate-400 uppercase">تعديل المراكز والقرى والإحداثيات</p>
         </div>
         <button onClick={() => setIsAddingDistrict(!isAddingDistrict)} className="p-4 bg-[#2D9469] text-white rounded-2xl shadow-lg active:scale-90 transition-all flex items-center gap-2">
            {isAddingDistrict ? <X className="h-5 w-5" /> : <><Plus className="h-5 w-5" /> إضافة مركز</>}
         </button>
      </div>

      {isAddingDistrict && (
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-50 space-y-6 animate-in zoom-in duration-300">
           <div className="flex items-center gap-4 flex-row-reverse">
              <div className="bg-emerald-50 p-4 rounded-2xl text-[#2D9469]"><Building className="h-6 w-6" /></div>
              <div className="flex-1">
                 <label className="text-[10px] font-black text-slate-400 block mb-1 text-right">اسم المركز الجديد</label>
                 <input 
                   autoFocus
                   value={newDistrictName} 
                   onChange={e => setNewDistrictName(e.target.value)} 
                   placeholder="اكتب اسم المركز..." 
                   className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right border-2 border-transparent focus:border-emerald-500 transition-all" 
                 />
              </div>
           </div>
           <button onClick={addDistrict} className="w-full bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg shadow-2xl active:scale-95 transition-all">
              تأكيد إضافة المركز
           </button>
        </div>
      )}

      <div className="space-y-4">
         {loading ? (
           <div className="py-20 flex justify-center"><Loader2 className="animate-spin h-10 w-10 text-emerald-500" /></div>
         ) : districts.length === 0 ? (
           <div className="py-24 text-center text-slate-300 font-bold border-4 border-dashed border-slate-50 rounded-[4rem]">لا توجد مراكز مضافة بعد</div>
         ) : districts.map(dist => (
           <div key={dist.id} className="bg-white rounded-[3rem] border border-slate-100 shadow-sm overflow-hidden transition-all">
              <div 
                className={`p-6 flex justify-between items-center transition-colors ${expandedDistrict === dist.id ? 'bg-slate-50' : 'hover:bg-slate-50/50'}`}
              >
                 <div className="flex gap-2 items-center">
                    <button onClick={() => setExpandedDistrict(expandedDistrict === dist.id ? null : dist.id)} className="p-3 bg-white shadow-sm text-slate-400 rounded-xl hover:text-[#2D9469]">
                       <ChevronDown className={`h-5 w-5 transition-transform duration-500 ${expandedDistrict === dist.id ? 'rotate-180' : ''}`} />
                    </button>
                    <button onClick={() => deleteDistrict(dist.id)} className="p-3 text-rose-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"><Trash2 className="h-4 w-4" /></button>
                 </div>

                 <div className="flex items-center gap-4 flex-row-reverse text-right flex-1">
                    <div className="bg-slate-100 p-3 rounded-2xl text-slate-400"><MapIcon className="h-5 w-5" /></div>
                    <div className="flex-1">
                       {editingDistrictId === dist.id ? (
                         <div className="flex gap-2 flex-row-reverse">
                            <input 
                              autoFocus
                              value={tempDistrictName}
                              onChange={e => setTempDistrictName(e.target.value)}
                              className="bg-white border-2 border-emerald-500 rounded-xl px-4 py-2 font-black text-sm text-right outline-none w-full"
                            />
                            <button onClick={() => saveDistrictName(dist.id)} className="bg-emerald-500 text-white p-2 rounded-xl"><Check className="h-4 w-4" /></button>
                            <button onClick={() => setEditingDistrictId(null)} className="bg-slate-200 text-slate-500 p-2 rounded-xl"><X className="h-4 w-4" /></button>
                         </div>
                       ) : (
                         <div className="flex items-center gap-2 justify-end group">
                            <button onClick={() => startEditDistrict(dist)} className="p-2 opacity-0 group-hover:opacity-100 text-slate-300 hover:text-[#2D9469] transition-all"><Edit3 className="h-4 w-4" /></button>
                            <h4 className="font-black text-slate-900" onClick={() => setExpandedDistrict(expandedDistrict === dist.id ? null : dist.id)}>مركز {dist.name}</h4>
                         </div>
                       )}
                       <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{dist.villages?.length || 0} قرية مسجلة</p>
                    </div>
                 </div>
              </div>

              {expandedDistrict === dist.id && (
                <div className="p-6 border-t border-slate-100 space-y-6 animate-in slide-in-from-top duration-300">
                   {/* قائمة القرى */}
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {dist.villages?.map(v => (
                        <div key={v.id} className="bg-slate-50 p-4 rounded-2xl flex justify-between items-center flex-row-reverse group transition-all hover:bg-white hover:shadow-md border border-transparent hover:border-emerald-100">
                           {editingVillageId === v.id ? (
                             <div className="w-full space-y-2">
                                <input 
                                  value={tempVillageData?.name || ''} 
                                  onChange={e => setTempVillageData(prev => prev ? {...prev, name: e.target.value} : null)}
                                  className="w-full bg-white p-2 rounded-lg text-xs font-black text-right outline-none border border-emerald-300" 
                                />
                                <div className="flex gap-2">
                                   <input 
                                     type="number" 
                                     value={tempVillageData?.center.lat || 0} 
                                     onChange={e => setTempVillageData(prev => prev ? {...prev, center: {...prev.center, lat: Number(e.target.value)}} : null)}
                                     className="flex-1 bg-white p-2 rounded-lg text-[10px] text-center outline-none border border-slate-200" 
                                   />
                                   <input 
                                     type="number" 
                                     value={tempVillageData?.center.lng || 0} 
                                     onChange={e => setTempVillageData(prev => prev ? {...prev, center: {...prev.center, lng: Number(e.target.value)}} : null)}
                                     className="flex-1 bg-white p-2 rounded-lg text-[10px] text-center outline-none border border-slate-200" 
                                   />
                                </div>
                                <div className="flex gap-2 pt-1">
                                   <button onClick={() => saveVillageChanges(dist.id)} className="flex-1 bg-emerald-500 text-white py-2 rounded-lg text-[10px] font-black">حفظ</button>
                                   <button onClick={() => setEditingVillageId(null)} className="flex-1 bg-slate-200 text-slate-500 py-2 rounded-lg text-[10px] font-black">إلغاء</button>
                                </div>
                             </div>
                           ) : (
                             <>
                               <div className="text-right">
                                  <p className="font-black text-slate-800 text-xs">{v.name}</p>
                                  <p className="text-[8px] font-bold text-slate-400" dir="ltr">{v.center.lat.toFixed(4)}, {v.center.lng.toFixed(4)}</p>
                               </div>
                               <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                  <button onClick={() => startEditVillage(v)} className="p-2 text-slate-400 hover:text-emerald-500"><Edit3 className="h-4 w-4" /></button>
                                  <button onClick={() => removeVillage(dist.id, v.id)} className="p-2 text-rose-200 hover:text-rose-500"><Trash2 className="h-4 w-4" /></button>
                               </div>
                             </>
                           )}
                        </div>
                      ))}
                      {(!dist.villages || dist.villages.length === 0) && (
                        <p className="col-span-full text-center text-slate-300 text-[10px] py-4 font-bold">لا توجد قرى في هذا المركز</p>
                      )}
                   </div>

                   {/* إضافة قرية جديدة */}
                   <div className="bg-emerald-50/30 p-6 rounded-[2.5rem] border-2 border-emerald-50 space-y-4">
                      <div className="text-right mb-2 flex items-center justify-end gap-2">
                         <h5 className="text-[10px] font-black text-[#2D9469] uppercase tracking-widest">إضافة منطقة جديدة لمركز {dist.name}</h5>
                         <PlusCircle className="h-4 w-4 text-[#2D9469]" />
                      </div>
                      <div className="grid grid-cols-1 gap-3">
                         <input 
                           value={newVillageData.name} 
                           onChange={e => setNewVillageData({...newVillageData, name: e.target.value})} 
                           placeholder="اسم القرية" 
                           className="w-full bg-white p-4 rounded-xl text-xs font-black outline-none text-right shadow-sm border border-transparent focus:border-emerald-300" 
                         />
                         <div className="grid grid-cols-2 gap-2">
                            <div className="space-y-1">
                               <label className="text-[8px] font-bold text-slate-400 block text-center">خط العرض (Lat)</label>
                               <input 
                                 type="number" 
                                 value={newVillageData.lat} 
                                 onChange={e => setNewVillageData({...newVillageData, lat: Number(e.target.value)})} 
                                 className="w-full bg-white p-4 rounded-xl text-[10px] font-bold outline-none text-center shadow-sm" 
                               />
                            </div>
                            <div className="space-y-1">
                               <label className="text-[8px] font-bold text-slate-400 block text-center">خط الطول (Lng)</label>
                               <input 
                                 type="number" 
                                 value={newVillageData.lng} 
                                 onChange={e => setNewVillageData({...newVillageData, lng: Number(e.target.value)})} 
                                 className="w-full bg-white p-4 rounded-xl text-[10px] font-bold outline-none text-center shadow-sm" 
                               />
                            </div>
                         </div>
                      </div>
                      <button onClick={() => addVillage(dist.id)} className="w-full bg-[#2D9469] text-white py-4 rounded-2xl font-black text-xs shadow-lg active:scale-95 transition-all">إضافة القرية للقاعدة</button>
                   </div>
                </div>
              )}
           </div>
         ))}
      </div>
    </div>
  );
};

// --- نافذة تعديل المستخدم الشاملة (Portrait Optimized) ---
const UserEditModal: React.FC<{ user: User, onClose: () => void }> = ({ user, onClose }) => {
  const [formData, setFormData] = useState({
    name: user.name || '',
    phone: user.phone || '',
    email: user.email || '',
    password: user.password || '',
    role: user.role || 'CUSTOMER',
    status: user.status || 'APPROVED',
    balance: user.wallet?.balance || 0,
    vehicleType: user.vehicleType || 'TOKTOK',
    plateNumber: user.plateNumber || ''
  });
  const [loading, setLoading] = useState(false);

  const handleSave = async () => {
    setLoading(true);
    try {
      await updateDoc(doc(db, "users", user.id), {
        name: formData.name,
        phone: formData.phone,
        email: formData.email,
        password: formData.password,
        role: formData.role,
        status: formData.status,
        vehicleType: formData.role === 'DRIVER' ? formData.vehicleType : null,
        plateNumber: formData.role === 'DRIVER' ? formData.plateNumber : null,
        "wallet.balance": Number(formData.balance)
      });
      onClose();
    } catch (e) {
      alert('حدث خطأ أثناء تحديث البيانات');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-white sm:bg-slate-950/80 sm:backdrop-blur-md flex items-end sm:items-center justify-center animate-in fade-in duration-300">
       <div className="bg-white w-full h-full sm:h-auto sm:max-w-2xl sm:rounded-[3rem] shadow-2xl flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden">
          {/* Header */}
          <div className="p-6 border-b border-slate-50 flex justify-between items-center sticky top-0 bg-white z-10 shadow-sm">
             <button onClick={onClose} className="p-3 bg-slate-50 text-slate-400 rounded-2xl active:scale-90 transition-all">
                <ChevronLeft className="h-6 w-6" />
             </button>
             <div className="text-right">
                <h3 className="text-xl font-black text-slate-900 tracking-tight">إدارة العضوية</h3>
                <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">تعديل كامل البيانات</p>
             </div>
          </div>

          {/* Scrollable Form Body */}
          <div className="flex-1 overflow-y-auto p-6 space-y-10 no-scrollbar pb-32">
             {/* القسم الأساسي */}
             <div className="space-y-4">
                <div className="flex items-center gap-2 justify-end text-slate-400 mb-2">
                   <span className="text-[10px] font-black uppercase tracking-widest">المعلومات الشخصية</span>
                   <UserIcon className="h-4 w-4" />
                </div>
                <div className="grid grid-cols-1 gap-4">
                   <div className="bg-slate-50 p-4 rounded-2xl border-2 border-transparent focus-within:border-emerald-500 transition-all shadow-inner">
                      <label className="text-[8px] font-black text-slate-400 mr-2 mb-1 block">الاسم بالكامل</label>
                      <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-transparent font-black text-sm outline-none text-right" />
                   </div>
                   <div className="grid grid-cols-2 gap-3">
                      <div className="bg-slate-50 p-4 rounded-2xl border-2 border-transparent focus-within:border-emerald-500 transition-all shadow-inner">
                         <label className="text-[8px] font-black text-slate-400 mr-2 mb-1 block">رقم الموبايل</label>
                         <input value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-transparent font-black text-sm outline-none text-left" dir="ltr" />
                      </div>
                      <div className="bg-slate-50 p-4 rounded-2xl border-2 border-transparent focus-within:border-emerald-500 transition-all shadow-inner">
                         <label className="text-[8px] font-black text-slate-400 mr-2 mb-1 block">البريد الإلكتروني</label>
                         <input value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full bg-transparent font-black text-[10px] outline-none text-left" dir="ltr" />
                      </div>
                   </div>
                </div>
             </div>

             {/* قسم الأمان والحالة */}
             <div className="space-y-4">
                <div className="flex items-center gap-2 justify-end text-rose-500 mb-2">
                   <span className="text-[10px] font-black uppercase tracking-widest">إدارة الحساب</span>
                   <ShieldAlert className="h-4 w-4" />
                </div>
