// --- مكون إدارة المطاعم (Restaurant Manager) ---
const RestaurantManager: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [activeRestId, setActiveRestId] = useState<string | null>(null);

  const [restData, setRestData] = useState<Partial<Restaurant>>({ 
    name: '', category: 'مشويات', photoURL: '', menuImageURL: '', menu: [], isOpen: true 
  });

  const [newItem, setNewItem] = useState({ name: '', price: 0, photoURL: '' });

  const photoRef = useRef<HTMLInputElement>(null);
  const menuPhotoRef = useRef<HTMLInputElement>(null);
  const itemPhotoRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImage = (e: React.ChangeEvent<HTMLInputElement>, target: 'REST' | 'ITEM' | 'MENU') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      if (target === 'REST') setRestData(prev => ({ ...prev, photoURL: reader.result as string }));
      else if (target === 'MENU') setRestData(prev => ({ ...prev, menuImageURL: reader.result as string }));
      else setNewItem(prev => ({ ...prev, photoURL: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = restData.id || `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, address: 'المنوفية', lat: 30.5, lng: 31.0
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menuImageURL: '', menu: [], isOpen: true });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
    await updateDoc(doc(db, "restaurants", rid), { menu });
    setNewItem({ name: '', price: 0, photoURL: '' });
  };

  return (
    <div className="space-y-6 animate-reveal">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 flex justify-between items-center flex-row-reverse">
         <div className="text-right">
            <h3 className="text-xl font-black text-slate-900">إدارة المطاعم</h3>
            <p className="text-[9px] font-bold text-slate-400 uppercase">قائمة الشركاء والمنيو</p>
         </div>
         <button onClick={() => setIsAdding(!isAdding)} className="p-4 bg-emerald-600 text-white rounded-2xl shadow-lg active:scale-90 transition-all">
            {isAdding ? <X className="h-5 w-5" /> : <Store className="h-5 w-5" />}
         </button>
      </div>

      {isAdding && (
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border-4 border-emerald-50 space-y-6 animate-in zoom-in duration-300">
           <div className="grid grid-cols-2 gap-4">
              <div 
                onClick={() => photoRef.current?.click()}
                className="w-full h-40 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-emerald-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden group transition-all"
              >
                 {restData.photoURL ? (
                    <img src={restData.photoURL} className="w-full h-full object-cover" />
                 ) : (
                    <>
                       <Camera className="h-10 w-10 text-emerald-200 mb-2" />
                       <p className="text-[10px] font-black text-emerald-300 uppercase">صورة الغلاف</p>
                    </>
                 )}
              </div>
              <div 
                onClick={() => menuPhotoRef.current?.click()}
                className="w-full h-40 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-amber-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden group transition-all"
              >
                 {restData.menuImageURL ? (
                    <img src={restData.menuImageURL} className="w-full h-full object-cover" />
                 ) : (
                    <>
                       <FileText className="h-10 w-10 text-amber-200 mb-2" />
                       <p className="text-[10px] font-black text-amber-300 uppercase">صورة المنيو</p>
                    </>
                 )}
              </div>
           </div>

           <input type="file" ref={photoRef} className="hidden" accept="image/*" onChange={e => handleImage(e, 'REST')} />
           <input type="file" ref={menuPhotoRef} className="hidden" accept="image/*" onChange={e => handleImage(e, 'MENU')} />

           <div className="space-y-4">
              <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} placeholder="اسم المطعم" className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right" />
              <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} placeholder="التصنيف (مثلاً: بيتزا، كريب)" className="w-full bg-slate-50 p-5 rounded-2xl font-black text-sm outline-none text-right" />
           </div>

           <button onClick={saveRestaurant} disabled={loading} className="w-full bg-slate-950 text-white py-6 rounded-[2rem] font-black text-lg shadow-2xl active:scale-95 transition-all">
              {loading ? <Loader2 className="animate-spin h-6 w-6 mx-auto" /> : 'إضافة المطعم الآن'}
           </button>
        </div>
      )}

      <div className="grid grid-cols-1 gap-6">
         {restaurants.map(rest => (
           <div key={rest.id} className="bg-white p-6 rounded-[3rem] border border-slate-50 shadow-sm space-y-6">
              <div className="flex justify-between items-start flex-row-reverse">
                 <div className="flex items-center gap-4 flex-row-reverse text-right">
                    <div className="w-16 h-16 bg-slate-950 rounded-2xl overflow-hidden shadow-lg border-2 border-white shrink-0">
                       {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-4 text-emerald-400" />}
                    </div>
                    <div>
                       <h4 className="font-black text-slate-900 text-lg leading-tight">{rest.name}</h4>
                       <p className="text-[10px] font-bold text-emerald-600">{rest.category}</p>
                    </div>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={async () => { if(confirm('حذف المطعم؟')) await deleteDoc(doc(db, "restaurants", rest.id)); }} className="p-3 bg-rose-50 text-rose-500 rounded-xl active:scale-90"><Trash2 className="h-4 w-4" /></button>
                    <button onClick={() => { setRestData(rest); setIsAdding(true); }} className="p-3 bg-slate-50 text-slate-400 rounded-xl active:scale-90"><Edit3 className="h-4 w-4" /></button>
                 </div>
              </div>

              {/* إدارة المنيو */}
              <div className="space-y-4">
                 <div className="flex items-center justify-between px-2 flex-row-reverse">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">قائمة الوجبات ({rest.menu?.length || 0})</p>
                    <div className="h-px flex-1 bg-slate-50 mr-4"></div>
                 </div>

                 <div className="grid gap-3">
                    {rest.menu?.map(item => (
                      <div key={item.id} className="bg-slate-50 p-4 rounded-2xl flex justify-between items-center flex-row-reverse group">
                         <div className="flex items-center gap-4 flex-row-reverse text-right">
                            <div className="w-12 h-12 bg-white rounded-xl overflow-hidden shrink-0 border border-slate-100 shadow-sm">
                               {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-3 text-slate-200" />}
                            </div>
                            <div>
                               <p className="font-black text-slate-800 text-xs">{item.name}</p>
                               <p className="text-[10px] font-bold text-emerald-600">{item.price} ج.م</p>
                            </div>
                         </div>
                         <button onClick={async () => {
                           const menu = rest.menu.filter(i => i.id !== item.id);
                           await updateDoc(doc(db, "restaurants", rest.id), { menu });
                         }} className="p-2 text-rose-300 hover:text-rose-500 transition-colors"><X className="h-4 w-4" /></button>
                      </div>
                    ))}
                 </div>

                 {/* إضافة وجبة جديدة */}
                 <div className="bg-emerald-50/30 p-5 rounded-[2.5rem] border-2 border-emerald-50 space-y-4">
                    <div className="flex gap-4 flex-row-reverse">
                       <div 
                         onClick={() => { setActiveRestId(rest.id); itemPhotoRef.current?.click(); }}
                         className="w-16 h-16 bg-white rounded-2xl border-2 border-dashed border-emerald-200 flex items-center justify-center cursor-pointer overflow-hidden shrink-0"
                       >
                          {activeRestId === rest.id && newItem.photoURL ? <img src={newItem.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-6 w-6 text-emerald-200" />}
                       </div>
                       <div className="flex-1 space-y-2">
                          <input value={activeRestId === rest.id ? newItem.name : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, name: e.target.value}); }} placeholder="اسم الوجبة" className="w-full bg-white p-3 rounded-xl text-xs font-black outline-none text-right" />
                          <div className="flex gap-2">
                             <input type="number" value={activeRestId === rest.id ? (newItem.price || '') : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, price: Number(e.target.value)}); }} placeholder="السعر" className="flex-1 bg-white p-3 rounded-xl text-xs font-black outline-none text-center" />
                             <button onClick={() => addMenuItem(rest.id)} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-black text-[10px] active:scale-90 transition-all">إضافة</button>
                          </div>
                       </div>
                    </div>
                    <input type="file" ref={itemPhotoRef} className="hidden" accept="image/*" onChange={e => handleImage(e, 'ITEM')} />
                 </div>
              </div>
           </div>
         ))}
      </div>
    </div>
  );
};

// --- المكون الرئيسي للسوبر أدمن ---
const SuperAdminDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'STATS' | 'USERS' | 'RESTAURANTS' | 'ADS' | 'VILLAGES'>('STATS');
  const [users, setUsers] = useState<User[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingUser, setEditingUser] = useState<User | null>(null);

  useEffect(() => {
    const unsubUsers = onSnapshot(collection(db, "users"), (snap) => setUsers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]));
    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("createdAt", "desc"), limit(100)), (snap) => setOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]));
    return () => { unsubUsers(); unsubOrders(); };
  }, []);

  const stats = {
    revenue: users.reduce((acc, curr) => acc + (curr.wallet?.balance || 0), 0),
    drivers: users.filter(u => u.role === 'DRIVER').length,
    customers: users.filter(u => u.role === 'CUSTOMER').length,
