                             className="w-full bg-slate-50 rounded-2xl p-6 text-xs font-bold outline-none border border-transparent focus:border-emerald-500 text-right min-h-[100px]"
                           />
                           <button onClick={handleCreateManualFoodOrder} disabled={isSubmitting || !dropoffVillage} className="w-full bg-emerald-600 text-white py-5 rounded-[1.8rem] font-black text-sm shadow-xl active:scale-95 transition-all">
                              {isSubmitting ? <Loader2 className="animate-spin h-5 w-5 mx-auto" /> : 'اطلب الحين'}
                           </button>
                        </div>
                      )}
                   </div>

                   <div className="grid grid-cols-1 gap-6 pb-10">
                      <div className="flex items-center justify-between px-2 mb-2">
                         <h4 className="text-xl font-black text-slate-800">أشهر مطاعم المنوفية</h4>
                         <Store className="h-5 w-5 text-slate-300" />
                      </div>
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-6 rounded-[3rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group active:scale-98">
                           <div className="flex items-center gap-5 flex-row-reverse text-right">
                              <div className="w-16 h-16 bg-slate-900 rounded-[1.8rem] flex items-center justify-center overflow-hidden border border-white/10 shadow-lg">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-4 text-emerald-400" />}
                              </div>
                              <div>
                                 <h4 className="text-lg font-black text-slate-800 group-hover:text-emerald-600 transition-colors leading-tight">{rest.name}</h4>
                                 <p className="text-[10px] font-bold text-slate-400">{rest.category}</p>
                              </div>
                           </div>
                           <ChevronLeft className="h-6 w-6 text-slate-300 transition-transform group-hover:-translate-x-2" />
                        </div>
                      ))}
                   </div>
                </div>
              )}

              {selectedCategory === 'PHARMACY' && (
                <div className="space-y-8 animate-in slide-in-from-left">
                   <LocationSelector 
                      label="مكان استلام الدواء" helper="سيوصل الكابتن الأدوية لهذا الموقع" icon={<MapPin />} iconBg="bg-emerald-500"
                      selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes}
                      onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes}
                   />

                   <div className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-sm space-y-6">
                      <div className="text-right">
                         <h4 className="font-black text-slate-800 flex items-center gap-3 flex-row-reverse"><Pill className="text-emerald-500 h-5 w-5" /> تفاصيل الطلب</h4>
                         <p className="text-[10px] font-bold text-slate-400 mt-1">اكتب أسماء الأدوية المطلوبة أو ارفع صورة الروشتة</p>
                      </div>

                      <textarea 
                        value={pharmacyNotes} onChange={e => setPharmacyNotes(e.target.value)}
                        placeholder="مثال: علبة بنادول، شريط أدول، علبة مناديل..."
                        className="w-full bg-slate-50 rounded-[2rem] p-6 font-bold text-sm outline-none border-2 border-transparent focus:border-emerald-500 min-h-[120px] text-right transition-all shadow-inner"
                      />

                      <div 
                        onClick={() => fileInputRef.current?.click()}
                        className={`w-full h-40 rounded-[2rem] border-4 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all ${prescriptionImage ? 'border-emerald-500 bg-emerald-50/50' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}
                      >
                         {prescriptionImage ? (
                           <div className="relative w-full h-full">
                              <img src={prescriptionImage} className="w-full h-full object-contain rounded-[1.5rem]" />
                              <button onClick={(e) => { e.stopPropagation(); setPrescriptionImage(null); }} className="absolute top-2 right-2 bg-rose-500 text-white p-2 rounded-full shadow-lg"><X className="h-4 w-4" /></button>
                           </div>
                         ) : (
                           <>
                             <Camera className="h-10 w-10 text-slate-300 mb-2" />
                             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إرفاق صورة الروشتة</p>
                           </>
                         )}
                         <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
                            const file = e.target.files?.[0];
