                         }} />
                      </div>

                      <button onClick={handleCreatePharmacyOrder} disabled={isSubmitting || !dropoffVillage} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
                         {isSubmitting ? <Loader2 className="animate-spin h-6 w-6" /> : <><Navigation2 className="h-6 w-6 text-emerald-400" /> اطلب الأدوية الحين</>}
                      </button>
                   </div>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-12">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="animate-in zoom-in space-y-12">
                    <div className="text-center space-y-6">
                       <div className="relative py-10">
                          <div className="absolute inset-0 flex items-center justify-center">
                             <div className="w-48 h-48 bg-emerald-500/10 rounded-full animate-ping"></div>
                          </div>
                          <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 inline-block border-4 border-emerald-50">
                             <Timer className="h-24 w-24 text-emerald-600 animate-pulse" />
                          </div>
                       </div>
                       <h2 className="text-3xl font-black text-slate-950 tracking-tighter leading-tight">جاري استقبال عروض الكباتن...</h2>
                       <p className="text-xs font-bold text-slate-400 px-10 leading-relaxed">طلبك يظهر الآن لكافة الكباتن المعتمدين في المنوفية. ستظهر العروض هنا فور إرسالها.</p>
                    </div>

                    <div className="space-y-4">
                       <div className="flex items-center justify-between px-4 flex-row-reverse">
                          <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">العروض الحالية ({incomingOffers.length})</h4>
                          <div className="h-px flex-1 bg-slate-100 mr-4"></div>
                       </div>

                       <div className="space-y-4">
                          {incomingOffers.map(offer => (
                            <div key={offer.id} className="bg-white p-8 rounded-[3rem] border-4 border-slate-50 shadow-xl flex justify-between items-center hover:border-emerald-500 transition-all animate-in slide-in-from-bottom group">
                               <div className="text-center space-y-2">
                                  <p className="text-3xl font-black text-emerald-700 tracking-tight">{offer.price} <span className="text-[10px] opacity-40 uppercase">ج.م</span></p>
                                  <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2.5 rounded-2xl font-black text-xs shadow-lg shadow-emerald-100 active:scale-90 transition-all group-hover:bg-slate-950">قبول العرض</button>
                               </div>
                               <div className="flex items-center gap-5 flex-row-reverse text-right">
                                  <div className="w-16 h-16 bg-slate-900 text-emerald-400 rounded-2xl flex items-center justify-center overflow-hidden border border-white shadow-md">
                                    {offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-8 w-8" />}
                                  </div>
                                  <div>
                                     <p className="font-black text-slate-900 text-lg leading-tight">{offer.driverName}</p>
                                     <div className="flex items-center gap-2 justify-end mt-1.5">
                                        <span className="text-[10px] font-black text-amber-500 bg-amber-50 px-3 py-1 rounded-full flex items-center gap-1.5 shadow-sm">
                                           {offer.driverRating} <Star className="h-3 w-3 fill-amber-400" />
                                        </span>
                                        <span className="text-[9px] font-black text-slate-400 uppercase">{offer.vehicleType === 'TOKTOK' ? 'توكتوك' : 'موتوسيكل'}</span>
                                     </div>
                                  </div>
                               </div>
                            </div>
                          ))}
                          {incomingOffers.length === 0 && (
                            <div className="py-24 text-center border-4 border-dashed border-slate-100 rounded-[3rem] bg-white/50 opacity-60">
                               <Loader2 className="h-8 w-8 animate-spin mx-auto text-slate-200 mb-4" />
                               <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">بانتظار أول كابتن...</p>
                            </div>
                          )}
                       </div>
                    </div>

                    <button onClick={async () => {
                       if(confirm('هل تريد إلغاء الطلب حقاً؟')) {
                          await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED });
                       }
                    }} className="w-full py-4 text-rose-500 font-black text-[10px] uppercase tracking-[0.4em] hover:bg-rose-50 rounded-2xl transition-all">إلغاء الطلب الحالي</button>
                 </div>
               ) : activeOrder.status === OrderStatus.DELIVERED ? (
                 <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                    <PartyPopper className="h-20 w-20 text-emerald-500 mx-auto animate-bounce" />
                    <h2 className="text-3xl font-black text-slate-950">وصلت بالسلامة!</h2>
                    <div className="bg-slate-50 p-8 rounded-[3rem] space-y-8">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4 block">قيم تجربة التوصيل</p>
                       <div className="flex justify-center gap-3">
                          {[1,2,3,4,5].map(s => (
                            <button key={s} onClick={() => setRating(s)} className="transition-all active:scale-75 border-none bg-transparent outline-none"><Star className={`h-12 w-12 ${rating >= s ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} /></button>
                          ))}
                       </div>
                       <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="رأيك يهمنا لتطوير وصلها..." className="w-full bg-white border-2 border-slate-100 rounded-[2rem] p-6 font-bold text-sm outline-none text-right shadow-inner" dir="rtl" />
                    </div>
                    <button onClick={async () => {
                      await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.DELIVERED_RATED, rating, feedback: feedback.trim(), ratedAt: Date.now() });
                      setFeedback('');
                    }} className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl">تأكيد التقييم <ThumbsUp className="h-8 w-8 inline mr-2" /></button>
                 </div>
               ) : (
                 <div className="animate-in zoom-in space-y-12">
                    <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                       <div className="text-right">
                          <p className="text-[11px] font-black opacity-60 uppercase mb-2">تتبع الرحلة</p>
                          <h3 className="text-2xl font-black leading-none">الكابتن في طريقه إليك</h3>
                       </div>
                       <div className="bg-white/20 p-5 rounded-full"><Navigation2 className="h-8 w-8 animate-bounce" /></div>
                    </div>

                    <div className="flex flex-col items-center gap-6">
                       <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden">
                         {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                       </div>
                       <div className="text-center">
                          <h4 className="text-3xl font-black text-slate-950 tracking-tight">{activeOrder.driverName}</h4>
                          <p className="label-strong mt-2 uppercase text-emerald-600 bg-emerald-50 px-6 py-2 rounded-full inline-block">كابتن معتمد • المنوفية</p>
                       </div>
                    </div>

                    <div className="grid grid-cols-2 gap-5">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-900 text-white py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95"><PhoneCall className="h-7 w-7" /> اتصال</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 active:scale-95"><MessageCircle className="h-7 w-7" /> محادثة</button>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all border-none bg-transparent ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;
